import { Outlet, useLocation } from 'react-router-dom';
import Sidebar from './Sidebar';

const pageTitles = {
    '/': 'Dashboard',
    '/appointments': 'Appointments',
    '/messages': 'Messages',
    '/upload-report': 'Upload Medical Report',
    '/ai-analysis': 'My Reports',
    '/lab-tests': 'Lab Tests',
    '/pharmacy': 'Pharmacy',
    '/payments': 'Payments',
    '/emergency': 'Emergency',
    '/profile': 'Profile',
};

const MainLayout = () => {
    return (
        <div className="light-layout">
            <Sidebar />
            <main className="light-main">
                <div className="light-content">
                    <Outlet />
                </div>
            </main>
        </div>
    );
};

export default MainLayout;

