import { useState, useEffect, useRef } from 'react';
import {
    HiOutlineCalendar, HiOutlineClock, HiOutlineVideoCamera,
    HiOutlineLocationMarker, HiOutlinePlus, HiOutlineX,
    HiOutlineUser, HiOutlineSearch, HiOutlineChevronDown
} from 'react-icons/hi';
import toast from 'react-hot-toast';
import { appointmentAPI, doctorAPI, patientAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';

const STATUS_COLORS = {
    scheduled: '#f59e0b', confirmed: '#06b6d4', 'in-progress': '#8b5cf6',
    completed: '#10b981', cancelled: '#ef4444', 'no-show': '#6b7280', pending: '#f59e0b'
};

const Appointments = () => {
    const { user } = useAuth();
    const isDoctor = user?.role === 'doctor';

    const [appointments, setAppointments] = useState([]);
    const [doctors, setDoctors] = useState([]);
    const [patients, setPatients] = useState([]);
    const [showBooking, setShowBooking] = useState(false);
    const [loading, setLoading] = useState(true);
    const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
    const [searchQuery, setSearchQuery] = useState('');
    const [dropdownOpen, setDropdownOpen] = useState(false);
    const dropdownRef = useRef(null);

    const [bookingData, setBookingData] = useState({
        doctorId: '', patientId: '', dateTime: '', type: 'in-person', reason: '', remarks: '', symptoms: ''
    });

    useEffect(() => { fetchData(); }, []);

    // Close dropdown when clicking outside
    useEffect(() => {
        const handleClickOutside = (e) => {
            if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
                setDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const fetchData = async () => {
        setLoading(true);
        try {
            const promises = [appointmentAPI.getAll()];
            if (isDoctor) promises.push(patientAPI.getAll());
            else promises.push(doctorAPI.getAll());

            const [aptRes, listRes] = await Promise.all(promises);
            setAppointments(aptRes.data.data || []);
            if (isDoctor) setPatients(listRes.data.data || []);
            else setDoctors(listRes.data.data || []);
        } catch {
            setAppointments([]);
            if (isDoctor) setPatients([]);
            else setDoctors([]);
            toast.error('Failed to load appointments');
        }
        setLoading(false);
    };

    const handleBook = async (e) => {
        e.preventDefault();
        try {
            const payload = {
                dateTime: bookingData.dateTime,
                type: bookingData.type,
                reason: bookingData.reason || bookingData.remarks,
                symptoms: bookingData.symptoms ? bookingData.symptoms.split(',').map(s => s.trim()) : [],
            };
            if (isDoctor) payload.patientId = bookingData.patientId;
            else payload.doctorId = bookingData.doctorId;

            await appointmentAPI.create(payload);
            toast.success('Appointment booked successfully!');
            setShowBooking(false);
            setBookingData({ doctorId: '', patientId: '', dateTime: '', type: 'in-person', reason: '', remarks: '', symptoms: '' });
            fetchData();
        } catch (err) {
            toast.error(err.response?.data?.message || 'Failed to book appointment');
        }
    };

    const handleCancel = async (id) => {
        try {
            await appointmentAPI.cancel(id);
            toast.success('Appointment cancelled');
            fetchData();
        } catch {
            toast.success('Cancelled (Demo)');
            setAppointments(prev => prev.map(a => a._id === id ? { ...a, status: 'cancelled' } : a));
        }
    };

    const generateCalendarDays = () => {
        const today = new Date();
        return Array.from({ length: 14 }, (_, i) => {
            const d = new Date(today);
            d.setDate(today.getDate() + i - 2);
            return d;
        });
    };

    const filteredSearch = (list, key) =>
        list.filter(item => item.userId?.name?.toLowerCase().includes(searchQuery.toLowerCase()));

    if (loading) return <div className="page-loader"><div className="spinner"></div></div>;

    return (
        <div className="appointments-page">
            <div className="page-header">
                <div>
                    <h1 className="page-title">Appointments</h1>
                    <p className="page-subtitle">
                        {isDoctor ? 'Manage your patient appointments' : 'Manage your medical appointments'}
                    </p>
                </div>
                <button className="btn-primary" onClick={() => setShowBooking(true)}>
                    <HiOutlinePlus className="w-5 h-5" />
                    <span>Book Appointment</span>
                </button>
            </div>

            {/* Calendar Strip */}
            <div className="calendar-strip">
                {generateCalendarDays().map((day, i) => {
                    const isSelected = day.toISOString().split('T')[0] === selectedDate;
                    const isToday = day.toDateString() === new Date().toDateString();
                    const hasAppt = appointments.some(a =>
                        new Date(a.dateTime).toDateString() === day.toDateString()
                    );
                    return (
                        <button
                            key={i}
                            className={`calendar-day ${isSelected ? 'selected' : ''} ${isToday ? 'today' : ''}`}
                            onClick={() => setSelectedDate(day.toISOString().split('T')[0])}
                        >
                            <span className="calendar-day-name">{day.toLocaleDateString('en', { weekday: 'short' })}</span>
                            <span className="calendar-day-num">{day.getDate()}</span>
                            {hasAppt && <span className="calendar-dot"></span>}
                        </button>
                    );
                })}
            </div>

            {/* Appointment Cards */}
            <div className="appointments-grid">
                {appointments.filter(a => a.dateTime.split('T')[0] === selectedDate).length === 0 ? (
                    <div className="empty-state">
                        <HiOutlineCalendar className="w-16 h-16 text-slate-600 mx-auto" />
                        <h3>No Appointments</h3>
                        <p>No appointments scheduled for this date</p>
                    </div>
                ) : (
                    appointments.filter(a => a.dateTime.split('T')[0] === selectedDate).map(apt => {
                        // For doctor view: show patient name; for patient view: show doctor name
                        const primaryName = isDoctor
                            ? (apt.patientId?.userId?.name || 'Patient')
                            : (apt.doctorId?.userId?.name || 'Doctor');
                        const primarySub = isDoctor
                            ? 'Patient'
                            : (apt.doctorId?.specialization || 'Specialist');

                        return (
                            <div key={apt._id} className="appointment-card">
                                <div className="appointment-card-header">
                                    <div className="appointment-card-avatar">
                                        {primaryName.charAt(0)}
                                    </div>
                                    <div>
                                        <h3>{primaryName}</h3>
                                        <p className="text-sm" style={{ color: '#94a3b8' }}>{primarySub}</p>
                                    </div>
                                    <span className="status-badge" style={{ '--badge-color': STATUS_COLORS[apt.status] }}>
                                        {apt.status}
                                    </span>
                                </div>
                                <div className="appointment-card-body">
                                    <div className="info-row">
                                        <HiOutlineCalendar className="w-4 h-4" />
                                        <span>{new Date(apt.dateTime).toLocaleDateString('en', { dateStyle: 'medium' })}</span>
                                    </div>
                                    <div className="info-row">
                                        <HiOutlineClock className="w-4 h-4" />
                                        <span>{new Date(apt.dateTime).toLocaleTimeString('en', { timeStyle: 'short' })}</span>
                                    </div>
                                    <div className="info-row">
                                        {apt.type === 'video'
                                            ? <HiOutlineVideoCamera className="w-4 h-4" />
                                            : <HiOutlineLocationMarker className="w-4 h-4" />}
                                        <span>{apt.type === 'video' ? 'Video Consultation' : 'In-Person Visit'}</span>
                                    </div>
                                    {/* Show other side's name for context */}
                                    {isDoctor && apt.patientId && (
                                        <div className="info-row">
                                            <HiOutlineUser className="w-4 h-4" />
                                            <span>Patient: {apt.patientId?.userId?.name}</span>
                                        </div>
                                    )}
                                    {!isDoctor && apt.doctorId && (
                                        <div className="info-row">
                                            <HiOutlineUser className="w-4 h-4" />
                                            <span>Doctor: {apt.doctorId?.userId?.name}</span>
                                        </div>
                                    )}
                                    {apt.reason && <p className="appointment-reason">{apt.reason}</p>}
                                </div>
                                <div className="appointment-card-actions">
                                    {apt.type === 'video' && apt.status !== 'cancelled' && apt.status !== 'completed' && new Date(apt.dateTime).toDateString() === new Date().toDateString() && (
                                        <a href="/video-consultation" className="btn-sm btn-primary-sm">
                                            <HiOutlineVideoCamera className="w-4 h-4" /> Join Call
                                        </a>
                                    )}
                                    {(apt.status === 'scheduled' || apt.status === 'pending') && (
                                        <button className="btn-sm btn-danger-sm" onClick={() => handleCancel(apt._id)}>Cancel</button>
                                    )}
                                </div>
                            </div>
                        );
                    })
                )}
            </div>

            {/* Booking Modal */}
            {showBooking && (
                <div className="modal-overlay" onClick={() => setShowBooking(false)}>
                    <div className="modal-content modal-lg" onClick={e => e.stopPropagation()}>
                        <div className="modal-header">
                            <h2>Book New Appointment</h2>
                            <button className="modal-close" onClick={() => setShowBooking(false)}>
                                <HiOutlineX className="w-5 h-5" />
                            </button>
                        </div>
                        <form onSubmit={handleBook} className="modal-body">

                            {/* DOCTOR view: searchable patient dropdown */}
                            {isDoctor && (
                                <div className="form-group" ref={dropdownRef}>
                                    <label>Select Patient</label>
                                    <div style={{ position: 'relative' }}>
                                        <HiOutlineSearch style={{
                                            position: 'absolute', left: 12, top: '50%',
                                            transform: 'translateY(-50%)', color: '#64748b', zIndex: 1
                                        }} />
                                        <input
                                            type="text"
                                            className="form-input"
                                            placeholder={bookingData.patientId
                                                ? patients.find(p => p._id === bookingData.patientId)?.userId?.name
                                                : 'Search patients...'}
                                            value={searchQuery}
                                            onFocus={() => setDropdownOpen(true)}
                                            onChange={e => { setSearchQuery(e.target.value); setDropdownOpen(true); setBookingData({ ...bookingData, patientId: '' }); }}
                                            style={{ paddingLeft: 36, paddingRight: 36 }}
                                            autoComplete="off"
                                        />
                                        <HiOutlineChevronDown style={{
                                            position: 'absolute', right: 12, top: '50%',
                                            transform: `translateY(-50%) rotate(${dropdownOpen ? 180 : 0}deg)`,
                                            color: '#64748b', transition: 'transform 0.2s', cursor: 'pointer'
                                        }} onClick={() => setDropdownOpen(o => !o)} />

                                        {dropdownOpen && (
                                            <div style={{
                                                position: 'absolute', top: 'calc(100% + 4px)', left: 0, right: 0,
                                                background: '#1e293b', border: '1px solid #334155', borderRadius: 10,
                                                maxHeight: 220, overflowY: 'auto', zIndex: 999,
                                                boxShadow: '0 8px 24px rgba(0,0,0,0.4)'
                                            }}>
                                                {filteredSearch(patients).length === 0 ? (
                                                    <div style={{ padding: '12px 16px', color: '#64748b', fontSize: '0.875rem' }}>No patients found</div>
                                                ) : filteredSearch(patients).map(pat => (
                                                    <div
                                                        key={pat._id}
                                                        onMouseDown={() => {
                                                            setBookingData({ ...bookingData, patientId: pat._id });
                                                            setSearchQuery('');
                                                            setDropdownOpen(false);
                                                        }}
                                                        style={{
                                                            padding: '10px 16px', cursor: 'pointer',
                                                            display: 'flex', alignItems: 'center', gap: 10,
                                                            background: bookingData.patientId === pat._id ? '#0ea5e920' : 'transparent',
                                                            borderLeft: bookingData.patientId === pat._id ? '3px solid #0ea5e9' : '3px solid transparent',
                                                            transition: 'background 0.15s'
                                                        }}
                                                        onMouseEnter={e => e.currentTarget.style.background = '#ffffff10'}
                                                        onMouseLeave={e => e.currentTarget.style.background = bookingData.patientId === pat._id ? '#0ea5e920' : 'transparent'}
                                                    >
                                                        <div style={{
                                                            width: 32, height: 32, borderRadius: '50%',
                                                            background: 'linear-gradient(135deg,#0ea5e9,#6366f1)',
                                                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                                                            color: '#fff', fontWeight: 700, fontSize: '0.85rem', flexShrink: 0
                                                        }}>{pat.userId?.name?.charAt(0)}</div>
                                                        <span style={{ color: '#e2e8f0', fontSize: '0.9rem' }}>{pat.userId?.name}</span>
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                    {bookingData.patientId && (
                                        <p style={{ marginTop: 6, color: '#10b981', fontSize: '0.82rem', display: 'flex', alignItems: 'center', gap: 4 }}>
                                            ✓ Selected: <strong>{patients.find(p => p._id === bookingData.patientId)?.userId?.name}</strong>
                                        </p>
                                    )}
                                </div>
                            )}

                            {/* PATIENT view: searchable doctor dropdown */}
                            {!isDoctor && (
                                <div className="form-group" ref={dropdownRef}>
                                    <label>Select Doctor</label>
                                    <div style={{ position: 'relative' }}>
                                        <HiOutlineSearch style={{
                                            position: 'absolute', left: 12, top: '50%',
                                            transform: 'translateY(-50%)', color: '#64748b', zIndex: 1
                                        }} />
                                        <input
                                            type="text"
                                            className="form-input"
                                            placeholder={bookingData.doctorId
                                                ? doctors.find(d => d._id === bookingData.doctorId)?.userId?.name
                                                : 'Search doctors...'}
                                            value={searchQuery}
                                            onFocus={() => setDropdownOpen(true)}
                                            onChange={e => { setSearchQuery(e.target.value); setDropdownOpen(true); setBookingData({ ...bookingData, doctorId: '' }); }}
                                            style={{ paddingLeft: 36, paddingRight: 36 }}
                                            autoComplete="off"
                                        />
                                        <HiOutlineChevronDown style={{
                                            position: 'absolute', right: 12, top: '50%',
                                            transform: `translateY(-50%) rotate(${dropdownOpen ? 180 : 0}deg)`,
                                            color: '#64748b', transition: 'transform 0.2s', cursor: 'pointer'
                                        }} onClick={() => setDropdownOpen(o => !o)} />

                                        {dropdownOpen && (
                                            <div style={{
                                                position: 'absolute', top: 'calc(100% + 4px)', left: 0, right: 0,
                                                background: '#1e293b', border: '1px solid #334155', borderRadius: 10,
                                                maxHeight: 220, overflowY: 'auto', zIndex: 999,
                                                boxShadow: '0 8px 24px rgba(0,0,0,0.4)'
                                            }}>
                                                {filteredSearch(doctors).length === 0 ? (
                                                    <div style={{ padding: '12px 16px', color: '#64748b', fontSize: '0.875rem' }}>No doctors found</div>
                                                ) : filteredSearch(doctors).map(doc => (
                                                    <div
                                                        key={doc._id}
                                                        onMouseDown={() => {
                                                            setBookingData({ ...bookingData, doctorId: doc._id });
                                                            setSearchQuery('');
                                                            setDropdownOpen(false);
                                                        }}
                                                        style={{
                                                            padding: '10px 16px', cursor: 'pointer',
                                                            display: 'flex', alignItems: 'center', gap: 10,
                                                            background: bookingData.doctorId === doc._id ? '#0ea5e920' : 'transparent',
                                                            borderLeft: bookingData.doctorId === doc._id ? '3px solid #0ea5e9' : '3px solid transparent',
                                                            transition: 'background 0.15s'
                                                        }}
                                                        onMouseEnter={e => e.currentTarget.style.background = '#ffffff10'}
                                                        onMouseLeave={e => e.currentTarget.style.background = bookingData.doctorId === doc._id ? '#0ea5e920' : 'transparent'}
                                                    >
                                                        <div style={{
                                                            width: 36, height: 36, borderRadius: '50%',
                                                            background: 'linear-gradient(135deg,#0ea5e9,#6366f1)',
                                                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                                                            color: '#fff', fontWeight: 700, fontSize: '0.9rem', flexShrink: 0
                                                        }}>{doc.userId?.name?.charAt(0)}</div>
                                                        <div style={{ flex: 1 }}>
                                                            <div style={{ color: '#e2e8f0', fontSize: '0.9rem', fontWeight: 500 }}>{doc.userId?.name}</div>
                                                            <div style={{ color: '#94a3b8', fontSize: '0.78rem' }}>{doc.specialization} · ₹{doc.consultationFee}</div>
                                                        </div>
                                                        {doc.rating?.average && (
                                                            <span style={{ color: '#f59e0b', fontSize: '0.8rem', fontWeight: 600 }}>⭐ {doc.rating.average}</span>
                                                        )}
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                    {bookingData.doctorId && (
                                        <p style={{ marginTop: 6, color: '#10b981', fontSize: '0.82rem', display: 'flex', alignItems: 'center', gap: 4 }}>
                                            ✓ Selected: <strong>{doctors.find(d => d._id === bookingData.doctorId)?.userId?.name}</strong>
                                        </p>
                                    )}
                                </div>
                            )}

                            <div className="form-row">
                                <div className="form-group">
                                    <label>Date &amp; Time</label>
                                    <input
                                        type="datetime-local"
                                        className="form-input"
                                        value={bookingData.dateTime}
                                        onChange={e => setBookingData({ ...bookingData, dateTime: e.target.value })}
                                        required
                                    />
                                </div>
                                <div className="form-group">
                                    <label>Consultation Type</label>
                                    <select className="form-select"
                                        value={bookingData.type}
                                        onChange={e => setBookingData({ ...bookingData, type: e.target.value })}>
                                        <option value="in-person">🏥 In-Person</option>
                                        <option value="video">📹 Video Call</option>
                                        <option value="phone">📞 Phone</option>
                                    </select>
                                </div>
                            </div>

                            <div className="form-group">
                                <label>{isDoctor ? 'Remarks / Notes' : 'Reason for Visit'}</label>
                                <input
                                    type="text"
                                    className="form-input"
                                    placeholder={isDoctor ? 'Add any notes for this appointment...' : 'Brief description of your concern...'}
                                    value={isDoctor ? bookingData.remarks : bookingData.reason}
                                    onChange={e => setBookingData(isDoctor
                                        ? { ...bookingData, remarks: e.target.value }
                                        : { ...bookingData, reason: e.target.value }
                                    )}
                                />
                            </div>

                            {!isDoctor && (
                                <div className="form-group">
                                    <label>Symptoms (comma separated)</label>
                                    <input
                                        type="text"
                                        className="form-input"
                                        placeholder="e.g., headache, fever, fatigue"
                                        value={bookingData.symptoms}
                                        onChange={e => setBookingData({ ...bookingData, symptoms: e.target.value })}
                                    />
                                </div>
                            )}

                            <div className="modal-actions">
                                <button type="button" className="btn-secondary" onClick={() => setShowBooking(false)}>Cancel</button>
                                <button type="submit" className="btn-primary">✓ Confirm Booking</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Appointments;

import { useState, useEffect } from 'react';
import {
    HiOutlinePlus,
    HiOutlinePencil,
    HiOutlineTrash,
    HiOutlineSearch,
    HiOutlinePhone,
    HiOutlineLocationMarker
} from 'react-icons/hi';
import { customerAPI } from '../services/api';
import toast from 'react-hot-toast';

const Customers = () => {
    const [customers, setCustomers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [showModal, setShowModal] = useState(false);
    const [editingCustomer, setEditingCustomer] = useState(null);
    const [searchQuery, setSearchQuery] = useState('');
    const [formData, setFormData] = useState({
        name: '',
        phone: '',
        alternatePhone: '',
        address: { street: '', city: '', state: '', pincode: '' },
        gstNumber: '',
        businessName: '',
        customerType: 'retail',
        creditLimit: 0,
        notes: ''
    });

    useEffect(() => {
        fetchCustomers();
    }, [searchQuery]);

    const fetchCustomers = async () => {
        try {
            const response = await customerAPI.getAll({ search: searchQuery });
            setCustomers(response.data.data);
        } catch (error) {
            toast.error('Failed to fetch customers');
        } finally {
            setLoading(false);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            if (editingCustomer) {
                await customerAPI.update(editingCustomer._id, formData);
                toast.success('Customer updated successfully');
            } else {
                await customerAPI.create(formData);
                toast.success('Customer added successfully');
            }
            setShowModal(false);
            setEditingCustomer(null);
            resetForm();
            fetchCustomers();
        } catch (error) {
            toast.error(error.response?.data?.message || 'Operation failed');
        }
    };

    const handleEdit = (customer) => {
        setEditingCustomer(customer);
        setFormData({
            name: customer.name,
            phone: customer.phone,
            alternatePhone: customer.alternatePhone || '',
            address: customer.address || { street: '', city: '', state: '', pincode: '' },
            gstNumber: customer.gstNumber || '',
            businessName: customer.businessName || '',
            customerType: customer.customerType,
            creditLimit: customer.creditLimit,
            notes: customer.notes || ''
        });
        setShowModal(true);
    };

    const handleDelete = async (id) => {
        if (window.confirm('Are you sure you want to delete this customer?')) {
            try {
                await customerAPI.delete(id);
                toast.success('Customer deleted');
                fetchCustomers();
            } catch (error) {
                toast.error('Failed to delete customer');
            }
        }
    };

    const resetForm = () => {
        setFormData({
            name: '',
            phone: '',
            alternatePhone: '',
            address: { street: '', city: '', state: '', pincode: '' },
            gstNumber: '',
            businessName: '',
            customerType: 'retail',
            creditLimit: 0,
            notes: ''
        });
    };

    const customerTypes = [
        { value: 'retail', label: 'Retail', color: 'badge-info' },
        { value: 'wholesale', label: 'Wholesale', color: 'badge-success' },
        { value: 'MCC', label: 'MCC', color: 'badge-warning' },
        { value: 'distributor', label: 'Distributor', color: 'badge-danger' }
    ];

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div className="relative flex-1 max-w-md">
                    <HiOutlineSearch className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                    <input
                        type="text"
                        placeholder="Search customers..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="input-field pl-12"
                    />
                </div>
                <button
                    onClick={() => { setShowModal(true); setEditingCustomer(null); resetForm(); }}
                    className="btn-primary flex items-center gap-2"
                >
                    <HiOutlinePlus className="w-5 h-5" />
                    Add Customer
                </button>
            </div>

            {/* Customer Grid */}
            {loading ? (
                <div className="flex justify-center py-12">
                    <div className="w-10 h-10 border-4 border-cyan-500/30 border-t-cyan-500 rounded-full animate-spin"></div>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {customers.map((customer) => (
                        <div key={customer._id} className="glass-card p-5 hover:scale-[1.02] transition-transform">
                            <div className="flex justify-between items-start mb-3">
                                <div>
                                    <h3 className="text-lg font-semibold text-white">{customer.name}</h3>
                                    {customer.businessName && (
                                        <p className="text-sm text-slate-400">{customer.businessName}</p>
                                    )}
                                </div>
                                <span className={`badge ${customerTypes.find(t => t.value === customer.customerType)?.color}`}>
                                    {customer.customerType}
                                </span>
                            </div>

                            <div className="space-y-2 text-sm">
                                <div className="flex items-center gap-2 text-slate-300">
                                    <HiOutlinePhone className="w-4 h-4 text-slate-400" />
                                    {customer.phone}
                                </div>
                                {customer.address?.city && (
                                    <div className="flex items-center gap-2 text-slate-300">
                                        <HiOutlineLocationMarker className="w-4 h-4 text-slate-400" />
                                        {customer.address.city}, {customer.address.state}
                                    </div>
                                )}
                            </div>

                            <div className="flex items-center justify-between mt-4 pt-4 border-t border-slate-700/50">
                                <div>
                                    <p className="text-xs text-slate-400">Balance</p>
                                    <p className={`font-semibold ${customer.currentBalance > 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                                        ₹{customer.currentBalance?.toLocaleString() || 0}
                                    </p>
                                </div>
                                <div className="flex gap-2">
                                    <button
                                        onClick={() => handleEdit(customer)}
                                        className="p-2 rounded-lg bg-slate-700/50 hover:bg-slate-600/50 text-slate-300 transition-colors"
                                    >
                                        <HiOutlinePencil className="w-4 h-4" />
                                    </button>
                                    <button
                                        onClick={() => handleDelete(customer._id)}
                                        className="p-2 rounded-lg bg-red-500/10 hover:bg-red-500/20 text-red-400 transition-colors"
                                    >
                                        <HiOutlineTrash className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {customers.length === 0 && !loading && (
                <div className="text-center py-12">
                    <p className="text-slate-400">No customers found. Add your first customer!</p>
                </div>
            )}

            {/* Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                    <div className="glass-card w-full max-w-lg max-h-[90vh] overflow-y-auto p-6">
                        <h2 className="text-xl font-semibold text-white mb-6">
                            {editingCustomer ? 'Edit Customer' : 'Add Customer'}
                        </h2>

                        <form onSubmit={handleSubmit} className="space-y-4">
                            <div className="grid grid-cols-2 gap-4">
                                <div className="col-span-2">
                                    <label className="block text-sm font-medium text-slate-300 mb-2">Customer Name *</label>
                                    <input
                                        type="text"
                                        value={formData.name}
                                        onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                        className="input-field"
                                        required
                                    />
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-slate-300 mb-2">Phone *</label>
                                    <input
                                        type="tel"
                                        value={formData.phone}
                                        onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                                        className="input-field"
                                        required
                                    />
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-slate-300 mb-2">Customer Type</label>
                                    <select
                                        value={formData.customerType}
                                        onChange={(e) => setFormData({ ...formData, customerType: e.target.value })}
                                        className="input-field"
                                    >
                                        {customerTypes.map(type => (
                                            <option key={type.value} value={type.value}>{type.label}</option>
                                        ))}
                                    </select>
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-slate-300 mb-2">Business Name</label>
                                    <input
                                        type="text"
                                        value={formData.businessName}
                                        onChange={(e) => setFormData({ ...formData, businessName: e.target.value })}
                                        className="input-field"
                                    />
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-slate-300 mb-2">GST Number</label>
                                    <input
                                        type="text"
                                        value={formData.gstNumber}
                                        onChange={(e) => setFormData({ ...formData, gstNumber: e.target.value })}
                                        className="input-field"
                                    />
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-slate-300 mb-2">City</label>
                                    <input
                                        type="text"
                                        value={formData.address.city}
                                        onChange={(e) => setFormData({ ...formData, address: { ...formData.address, city: e.target.value } })}
                                        className="input-field"
                                    />
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-slate-300 mb-2">Credit Limit (₹)</label>
                                    <input
                                        type="number"
                                        value={formData.creditLimit}
                                        onChange={(e) => setFormData({ ...formData, creditLimit: parseInt(e.target.value) || 0 })}
                                        className="input-field"
                                    />
                                </div>
                            </div>

                            <div className="flex justify-end gap-3 pt-4">
                                <button
                                    type="button"
                                    onClick={() => { setShowModal(false); setEditingCustomer(null); }}
                                    className="btn-secondary"
                                >
                                    Cancel
                                </button>
                                <button type="submit" className="btn-primary">
                                    {editingCustomer ? 'Update' : 'Add'} Customer
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Customers;

import { useState } from 'react';
import { HiOutlineExclamation, HiOutlineLocationMarker, HiOutlinePhone } from 'react-icons/hi';
import toast from 'react-hot-toast';
import { alertAPI } from '../services/api';

const EmergencyAlert = () => {
    const [sending, setSending] = useState(false);
    const [alertSent, setAlertSent] = useState(false);
    const [description, setDescription] = useState('');
    const [countdown, setCountdown] = useState(null);

    const sendEmergency = async () => {
        setSending(true);
        // Countdown before sending
        let count = 3;
        setCountdown(count);
        const timer = setInterval(() => {
            count--;
            setCountdown(count);
            if (count <= 0) {
                clearInterval(timer);
                setCountdown(null);
                triggerAlert();
            }
        }, 1000);
    };

    const triggerAlert = async () => {
        try {
            await alertAPI.sendEmergency({
                description: description || 'Emergency assistance needed',
                location: { latitude: 28.6139, longitude: 77.2090, address: 'Current Location' }
            });
        } catch (err) {
            // Continue with mock
        }
        setAlertSent(true);
        setSending(false);
        toast.success('Emergency alert sent! Help is on the way.');
    };

    const cancelAlert = () => {
        setSending(false);
        setCountdown(null);
        toast('Emergency alert cancelled');
    };

    if (alertSent) {
        return (
            <div className="emergency-page">
                <div className="emergency-sent">
                    <div className="emergency-sent-icon pulse-ring">
                        <span>🚑</span>
                    </div>
                    <h1>Emergency Alert Sent!</h1>
                    <p>Help is on the way. Stay calm and wait for assistance.</p>

                    <div className="emergency-info-cards">
                        <div className="emergency-info-card">
                            <HiOutlineLocationMarker className="w-6 h-6" />
                            <div>
                                <h4>Your Location Shared</h4>
                                <p>GPS coordinates sent to nearest hospital</p>
                            </div>
                        </div>
                        <div className="emergency-info-card">
                            <HiOutlinePhone className="w-6 h-6" />
                            <div>
                                <h4>Hospital Notified</h4>
                                <p>City Hospital – Estimated arrival: 8 min</p>
                            </div>
                        </div>
                        <div className="emergency-info-card">
                            <span className="text-xl">👨‍⚕️</span>
                            <div>
                                <h4>Doctor On Call</h4>
                                <p>Dr. Emergency Support connecting...</p>
                            </div>
                        </div>
                    </div>

                    <div className="emergency-actions">
                        <a href="tel:102" className="btn-emergency-call">
                            <HiOutlinePhone className="w-5 h-5" /> Call Ambulance (102)
                        </a>
                        <button className="btn-secondary" onClick={() => setAlertSent(false)}>
                            Send Another Alert
                        </button>
                    </div>

                    <div className="emergency-timeline">
                        <h3>Response Timeline</h3>
                        <div className="timeline">
                            <div className="timeline-item done">
                                <div className="timeline-dot">✓</div>
                                <div><strong>Alert Sent</strong><span>Just now</span></div>
                            </div>
                            <div className="timeline-item active">
                                <div className="timeline-dot pulse"></div>
                                <div><strong>Hospital Notified</strong><span>Processing...</span></div>
                            </div>
                            <div className="timeline-item">
                                <div className="timeline-dot"></div>
                                <div><strong>Ambulance Dispatched</strong><span>Pending</span></div>
                            </div>
                            <div className="timeline-item">
                                <div className="timeline-dot"></div>
                                <div><strong>Help Arrives</strong><span>ETA: 8 min</span></div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="emergency-page">
            <div className="emergency-container">
                <div className="emergency-warning">
                    <HiOutlineExclamation className="w-8 h-8" />
                    <span>Use only in genuine medical emergencies</span>
                </div>

                <div className="emergency-button-wrapper">
                    {countdown !== null ? (
                        <div className="emergency-countdown">
                            <div className="countdown-number">{countdown}</div>
                            <p>Sending alert in...</p>
                            <button className="btn-cancel-emergency" onClick={cancelAlert}>Cancel</button>
                        </div>
                    ) : (
                        <button className="emergency-big-button" onClick={sendEmergency} disabled={sending}>
                            <span className="emergency-btn-icon">🆘</span>
                            <span className="emergency-btn-text">EMERGENCY</span>
                            <span className="emergency-btn-subtext">Tap to send alert</span>
                        </button>
                    )}
                </div>

                <div className="emergency-form">
                    <div className="form-group">
                        <label>Describe the emergency (optional)</label>
                        <textarea className="form-textarea" rows={2}
                            placeholder="e.g., Chest pain, difficulty breathing..."
                            value={description} onChange={e => setDescription(e.target.value)} />
                    </div>
                </div>

                <div className="emergency-features">
                    <div className="feature-item">
                        <span>📍</span>
                        <div>
                            <h4>Live Location</h4>
                            <p>Your GPS location will be shared automatically</p>
                        </div>
                    </div>
                    <div className="feature-item">
                        <span>🏥</span>
                        <div>
                            <h4>Nearest Hospital</h4>
                            <p>Alert sent to the closest emergency room</p>
                        </div>
                    </div>
                    <div className="feature-item">
                        <span>📱</span>
                        <div>
                            <h4>SMS Notification</h4>
                            <p>Emergency contacts will be notified automatically</p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default EmergencyAlert;

import { useState, useEffect } from 'react';
import {
    HiOutlineCalendar, HiOutlineChatAlt2, HiOutlineDocumentReport,
    HiOutlineUsers, HiOutlineCurrencyRupee, HiOutlineBell,
    HiOutlineTrendingUp, HiOutlineClipboardCheck, HiOutlineHeart
} from 'react-icons/hi';
import { appointmentAPI, patientAPI, doctorAPI, labTestAPI, messageAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';
import { Link } from 'react-router-dom';

const HealthDashboard = () => {
    const { user } = useAuth();
    const isDoctor = user?.role === 'doctor';
    const isPatient = user?.role === 'patient';

    const [appointments, setAppointments] = useState([]);
    const [allUpcoming, setAllUpcoming] = useState([]);
    const [stats, setStats] = useState({ appts: 0, count2: 0, count3: 0, count4: 0 });
    const [activity, setActivity] = useState([]);
    const [hoveredCard, setHoveredCard] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => { loadDashboard(); }, []);

    const loadDashboard = async () => {
        setLoading(true);
        try {
            const [apptRes] = await Promise.all([appointmentAPI.getAll()]);
            const appts = apptRes.data.data || [];

            // Sort: upcoming first
            const upcoming = appts
                .filter(a => new Date(a.dateTime) >= new Date() && a.status !== 'cancelled')
                .sort((a, b) => new Date(a.dateTime) - new Date(b.dateTime));

            setAppointments(upcoming.slice(0, 3));
            setAllUpcoming(upcoming);

            // Build stats based on role
            if (isPatient) {
                try {
                    const [labRes, msgRes] = await Promise.all([
                        labTestAPI.getAll(),
                        messageAPI.getConversations()
                    ]);
                    const labs = labRes.data.data || [];
                    const msgs = msgRes.data.data || [];
                    setStats({
                        appts: appts.filter(a => new Date(a.dateTime) >= new Date() && a.status !== 'cancelled').length,
                        count2: 0,
                        count3: labs.length,
                        count4: msgs.reduce((acc, c) => acc + (c.unreadCount || 0), 0),
                    });
                } catch {
                    setStats({ appts: upcoming.length, count2: 0, count3: 0, count4: 0 });
                }
            } else if (isDoctor) {
                const today = new Date().toDateString();
                const todayAppts = appts.filter(a => new Date(a.dateTime).toDateString() === today);
                const pending = appts.filter(a => a.status === 'scheduled' || a.status === 'pending');
                setStats({
                    appts: todayAppts.length,
                    count2: appts.filter(a => new Date(a.dateTime) >= new Date()).length,
                    count3: pending.length,
                    count4: 0,
                });
            }

            // Build activity from appointments
            const recentAppts = [...appts]
                .sort((a, b) => new Date(b.dateTime) - new Date(a.dateTime))
                .slice(0, 5)
                .map(a => {
                    const isUpcoming = new Date(a.dateTime) >= new Date();
                    const otherName = isDoctor
                        ? (a.patientId?.userId?.name || 'Patient')
                        : (a.doctorId?.userId?.name || 'Doctor');
                    return {
                        id: a._id,
                        icon: a.status === 'completed' ? '✅' : a.type === 'video' ? '📹' : '🏥',
                        text: isUpcoming
                            ? `Upcoming appointment with ${otherName}`
                            : `Appointment with ${otherName} — ${a.status}`,
                        time: formatRelative(a.dateTime),
                    };
                });
            setActivity(recentAppts);
        } catch {
            // Silent — show empty state
        } finally {
            setLoading(false);
        }
    };

    const formatRelative = (date) => {
        const d = new Date(date);
        const diff = Date.now() - d.getTime();
        if (diff < 0) {
            const abs = -diff;
            if (abs < 3600000) return `in ${Math.floor(abs / 60000)}m`;
            if (abs < 86400000) return `Today, ${d.toLocaleTimeString('en', { timeStyle: 'short' })}`;
            return d.toLocaleDateString('en', { month: 'short', day: 'numeric' });
        }
        if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
        if (diff < 86400000) return `${Math.floor(diff / 3600000)}h ago`;
        return `${Math.floor(diff / 86400000)}d ago`;
    };

    const patientStatCards = [
        { label: 'Upcoming Appointments', value: stats.appts, icon: HiOutlineCalendar, color: '#06b6d4', bg: 'rgba(6,182,212,0.1)' },
        { label: 'Prescriptions', value: stats.count2, icon: HiOutlineClipboardCheck, color: '#8b5cf6', bg: 'rgba(139,92,246,0.1)' },
        { label: 'Lab Reports', value: stats.count3, icon: HiOutlineDocumentReport, color: '#10b981', bg: 'rgba(16,185,129,0.1)' },
        { label: 'Unread Messages', value: stats.count4, icon: HiOutlineChatAlt2, color: '#f59e0b', bg: 'rgba(245,158,11,0.1)' },
    ];

    const doctorStatCards = [
        { label: "Today's Appointments", value: stats.appts, icon: HiOutlineCalendar, color: '#06b6d4', bg: 'rgba(6,182,212,0.1)' },
        { label: 'Total Upcoming', value: stats.count2, icon: HiOutlineUsers, color: '#8b5cf6', bg: 'rgba(139,92,246,0.1)' },
        { label: 'Pending Reviews', value: stats.count3, icon: HiOutlineDocumentReport, color: '#f59e0b', bg: 'rgba(245,158,11,0.1)' },
        { label: 'Messages', value: stats.count4, icon: HiOutlineChatAlt2, color: '#10b981', bg: 'rgba(16,185,129,0.1)' },
    ];

    const statCards = isDoctor ? doctorStatCards : patientStatCards;

    return (
        <div className="health-dashboard">
            {/* Welcome */}
            <div className="dashboard-welcome">
                <div>
                    <h1 className="dashboard-welcome-title">
                        Welcome back, <span className="gradient-text">{user?.name || 'User'}</span> 👋
                    </h1>
                    <p className="dashboard-welcome-subtitle">
                        {isDoctor ? "Here's your patient schedule for today" : 'Your health at a glance'}
                    </p>
                </div>
            </div>

            {/* Stats Grid — real counts */}
            <div className="stats-grid">
                {statCards.map((stat, i) => (
                    <div key={i} className="stat-card-health" style={{ '--stat-color': stat.color, position: 'relative' }}
                        onMouseEnter={() => setHoveredCard(i)}
                        onMouseLeave={() => setHoveredCard(null)}>
                        <div className="stat-icon-wrapper" style={{ background: stat.bg }}>
                            <stat.icon className="w-6 h-6" style={{ color: stat.color }} />
                        </div>
                        <div className="stat-info">
                            <p className="stat-label">{stat.label}</p>
                            <h3 className="stat-value" style={{ color: stat.color }}>
                                {loading ? '…' : stat.value}
                            </h3>
                        </div>
                        {/* Dropdown for upcoming appointments */}
                        {(stat.label === 'Upcoming Appointments' || stat.label === 'Total Upcoming') && hoveredCard === i && allUpcoming.length > 0 && (
                            <div style={{
                                position: 'absolute', top: '100%', left: 0, minWidth: '240px', zIndex: 100,
                                background: '#1e293b', padding: '12px', borderRadius: '10px',
                                boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.5)',
                                border: '1px solid #334155', maxHeight: '300px', overflowY: 'auto', marginTop: '10px'
                            }}>
                                <h4 style={{ fontSize: '0.8rem', textTransform: 'uppercase', letterSpacing: '0.05em', color: '#94a3b8', marginBottom: '8px', borderBottom: '1px solid #334155', paddingBottom: '6px' }}>All Upcoming</h4>
                                {allUpcoming.map(a => {
                                    const otherName = isDoctor ? (a.patientId?.userId?.name || 'Patient') : (a.doctorId?.userId?.name || 'Doctor');
                                    return (
                                        <div key={a._id} style={{ display: 'flex', justifyContent: 'space-between', padding: '8px 0', borderBottom: '1px solid rgba(255,255,255,0.05)', fontSize: '0.85rem' }}>
                                            <div style={{ color: '#e2e8f0', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: '140px' }}>{otherName}</div>
                                            <div style={{ color: '#0ea5e9', fontWeight: '500' }}>{new Date(a.dateTime).toLocaleDateString('en', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}</div>
                                        </div>
                                    )
                                })}
                            </div>
                        )}
                    </div>
                ))}
            </div>

            {/* Main Content Grid */}
            <div className="dashboard-content-grid">
                {/* Upcoming Appointments — real data */}
                <div className="dashboard-section-card">
                    <div className="section-header">
                        <h2><HiOutlineCalendar className="inline w-5 h-5 mr-2" />Upcoming Appointments</h2>
                        <Link to="/appointments" className="section-link">View All →</Link>
                    </div>
                    <div className="appointment-list">
                        {loading ? (
                            <div style={{ textAlign: 'center', padding: '2rem', color: '#64748b' }}>
                                <div className="spinner" style={{ margin: '0 auto' }} />
                            </div>
                        ) : appointments.length === 0 ? (
                            <div className="empty-state" style={{ padding: '1.5rem' }}>
                                <span style={{ fontSize: '2rem' }}>📅</span>
                                <h3>No upcoming appointments</h3>
                                <p>
                                    <Link to="/appointments" style={{ color: '#06b6d4' }}>Book an appointment</Link>
                                </p>
                            </div>
                        ) : appointments.map(apt => {
                            const doctorName = apt.doctorId?.userId?.name || 'Doctor';
                            const patientName = apt.patientId?.userId?.name || 'Patient';
                            const specialty = apt.doctorId?.specialization || '';
                            const displayName = isDoctor ? patientName : doctorName;
                            const displaySub = isDoctor ? '' : specialty;
                            return (
                                <div key={apt._id} className="appointment-item">
                                    <div className="appointment-avatar">
                                        {displayName.charAt(isDoctor ? 0 : 4) || displayName.charAt(0)}
                                    </div>
                                    <div className="appointment-details">
                                        <h4>{displayName}</h4>
                                        {displaySub && <p className="text-sm text-slate-400">{displaySub}</p>}
                                        <div className="appointment-meta">
                                            <span className="appointment-date">
                                                {new Date(apt.dateTime).toLocaleString('en', { dateStyle: 'medium', timeStyle: 'short' })}
                                            </span>
                                            <span className={`appointment-type ${apt.type === 'video' ? 'type-video' : 'type-inperson'}`}>
                                                {apt.type === 'video' ? '📹 Video' : '🏥 In-Person'}
                                            </span>
                                        </div>
                                    </div>
                                    <span className={`status-badge`} style={{ '--badge-color': apt.status === 'confirmed' ? '#06b6d4' : '#f59e0b' }}>
                                        {apt.status}
                                    </span>
                                </div>
                            );
                        })}
                    </div>
                </div>

                {/* Recent Activity — from real appointments */}
                <div className="dashboard-section-card">
                    <div className="section-header">
                        <h2><HiOutlineTrendingUp className="inline w-5 h-5 mr-2" />Recent Activity</h2>
                    </div>
                    <div className="activity-list">
                        {loading ? (
                            <div style={{ textAlign: 'center', padding: '2rem' }}><div className="spinner" style={{ margin: '0 auto' }} /></div>
                        ) : activity.length === 0 ? (
                            <div className="empty-state" style={{ padding: '1.5rem' }}>
                                <span style={{ fontSize: '2rem' }}>📋</span>
                                <h3>No recent activity</h3>
                            </div>
                        ) : activity.map(a => (
                            <div key={a.id} className="activity-item">
                                <span className="activity-icon">{a.icon}</span>
                                <div className="activity-details">
                                    <p>{a.text}</p>
                                    <span className="activity-time">{a.time}</span>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* Quick Actions */}
            <div className="quick-actions">
                <h2 className="section-title">Quick Actions</h2>
                <div className="quick-actions-grid">
                    <Link to="/appointments" className="quick-action-btn">
                        <HiOutlineCalendar className="w-8 h-8" />
                        <span>Book Appointment</span>
                    </Link>
                    <Link to="/upload-report" className="quick-action-btn">
                        <HiOutlineDocumentReport className="w-8 h-8" />
                        <span>Upload Report</span>
                    </Link>
                    <Link to="/ai-analysis" className="quick-action-btn">
                        <span className="text-2xl">🤖</span>
                        <span>AI Analysis</span>
                    </Link>
                    <Link to="/messages" className="quick-action-btn">
                        <HiOutlineChatAlt2 className="w-8 h-8" />
                        <span>Messages</span>
                    </Link>
                    <Link to="/emergency" className="quick-action-btn emergency">
                        <HiOutlineBell className="w-8 h-8" />
                        <span>Emergency</span>
                    </Link>
                    <Link to="/payments" className="quick-action-btn">
                        <HiOutlineCurrencyRupee className="w-8 h-8" />
                        <span>Payments</span>
                    </Link>
                </div>
            </div>
        </div>
    );
};

export default HealthDashboard;

import { useState, useEffect } from 'react';
import {
    HiOutlinePlus,
    HiOutlineCube,
    HiOutlineExclamation,
    HiOutlineArrowUp,
    HiOutlineArrowDown
} from 'react-icons/hi';
import { inventoryAPI, storageAPI } from '../services/api';
import toast from 'react-hot-toast';

const Inventory = () => {
    const [inventory, setInventory] = useState([]);
    const [storages, setStorages] = useState([]);
    const [stats, setStats] = useState(null);
    const [loading, setLoading] = useState(true);
    const [showModal, setShowModal] = useState(false);
    const [modalType, setModalType] = useState('add'); // 'add', 'entry', 'deduct'
    const [selectedInventory, setSelectedInventory] = useState(null);
    const [formData, setFormData] = useState({
        storageId: '',
        productType: 'Ice Block',
        quantity: 0,
        pricePerUnit: 0,
        unit: 'kg',
        batchNumber: '',
        lowStockThreshold: 100
    });

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        try {
            const [invRes, storRes, statsRes] = await Promise.all([
                inventoryAPI.getAll(),
                storageAPI.getAll(),
                inventoryAPI.getStats()
            ]);
            setInventory(invRes.data.data);
            setStorages(storRes.data.data);
            setStats(statsRes.data.data);
        } catch (error) {
            toast.error('Failed to fetch data');
        } finally {
            setLoading(false);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            if (modalType === 'add') {
                await inventoryAPI.create(formData);
                toast.success('Inventory item created');
            } else if (modalType === 'entry') {
                await inventoryAPI.addStock({
                    inventoryId: selectedInventory._id,
                    quantity: formData.quantity,
                    batchNumber: formData.batchNumber,
                    notes: formData.notes
                });
                toast.success('Stock added successfully');
            } else if (modalType === 'deduct') {
                await inventoryAPI.deductStock({
                    inventoryId: selectedInventory._id,
                    quantity: formData.quantity,
                    type: formData.deductType || 'waste',
                    notes: formData.notes
                });
                toast.success('Stock deducted');
            }
            setShowModal(false);
            resetForm();
            fetchData();
        } catch (error) {
            toast.error(error.response?.data?.message || 'Operation failed');
        }
    };

    const openStockEntry = (item) => {
        setSelectedInventory(item);
        setModalType('entry');
        setFormData({ quantity: 0, batchNumber: '', notes: '' });
        setShowModal(true);
    };

    const openStockDeduct = (item) => {
        setSelectedInventory(item);
        setModalType('deduct');
        setFormData({ quantity: 0, deductType: 'waste', notes: '' });
        setShowModal(true);
    };

    const resetForm = () => {
        setFormData({
            storageId: '',
            productType: 'Ice Block',
            quantity: 0,
            pricePerUnit: 0,
            unit: 'kg',
            batchNumber: '',
            lowStockThreshold: 100
        });
        setSelectedInventory(null);
    };

    return (
        <div className="space-y-6">
            {/* Stats */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <div className="stat-card">
                    <div className="flex items-center gap-3">
                        <div className="p-3 rounded-xl bg-gradient-to-br from-blue-500 to-cyan-500">
                            <HiOutlineCube className="w-6 h-6 text-white" />
                        </div>
                        <div>
                            <p className="text-sm text-slate-400">Total Stock</p>
                            <p className="text-2xl font-bold text-white">{stats?.totalQuantity?.toLocaleString() || 0} kg</p>
                        </div>
                    </div>
                </div>

                <div className="stat-card">
                    <div className="flex items-center gap-3">
                        <div className="p-3 rounded-xl bg-gradient-to-br from-red-500 to-orange-500">
                            <HiOutlineExclamation className="w-6 h-6 text-white" />
                        </div>
                        <div>
                            <p className="text-sm text-slate-400">Low Stock Items</p>
                            <p className="text-2xl font-bold text-white">{stats?.lowStockItems || 0}</p>
                        </div>
                    </div>
                </div>

                <div className="stat-card">
                    <div className="flex items-center gap-3">
                        <div className="p-3 rounded-xl bg-gradient-to-br from-emerald-500 to-green-500">
                            <HiOutlineArrowUp className="w-6 h-6 text-white" />
                        </div>
                        <div>
                            <p className="text-sm text-slate-400">Storage Capacity</p>
                            <p className="text-2xl font-bold text-white">{stats?.storageCapacity?.toLocaleString() || 0} kg</p>
                        </div>
                    </div>
                </div>

                <div className="stat-card">
                    <div className="flex items-center gap-3">
                        <div className="p-3 rounded-xl bg-gradient-to-br from-purple-500 to-pink-500">
                            <HiOutlineArrowDown className="w-6 h-6 text-white" />
                        </div>
                        <div>
                            <p className="text-sm text-slate-400">Storage Used</p>
                            <p className="text-2xl font-bold text-white">{stats?.storageUsed?.toLocaleString() || 0} kg</p>
                        </div>
                    </div>
                </div>
            </div>

            {/* Actions */}
            <div className="flex justify-end">
                <button
                    onClick={() => { setModalType('add'); setShowModal(true); resetForm(); }}
                    className="btn-primary flex items-center gap-2"
                >
                    <HiOutlinePlus className="w-5 h-5" />
                    Add Inventory
                </button>
            </div>

            {/* Inventory Table */}
            {loading ? (
                <div className="flex justify-center py-12">
                    <div className="w-10 h-10 border-4 border-cyan-500/30 border-t-cyan-500 rounded-full animate-spin"></div>
                </div>
            ) : (
                <div className="glass-card overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead>
                                <tr className="border-b border-slate-700">
                                    <th className="text-left p-4 text-slate-400 font-medium">Product</th>
                                    <th className="text-left p-4 text-slate-400 font-medium">Storage</th>
                                    <th className="text-right p-4 text-slate-400 font-medium">Quantity</th>
                                    <th className="text-right p-4 text-slate-400 font-medium">Price/Unit</th>
                                    <th className="text-center p-4 text-slate-400 font-medium">Status</th>
                                    <th className="text-center p-4 text-slate-400 font-medium">Actions</th>
                                </tr>
                            </thead>
                            <tbody>
                                {inventory.map((item) => (
                                    <tr key={item._id} className="table-row">
                                        <td className="p-4">
                                            <div>
                                                <p className="text-white font-medium">{item.productType}</p>
                                                <p className="text-sm text-slate-400">Batch: {item.batchNumber || 'N/A'}</p>
                                            </div>
                                        </td>
                                        <td className="p-4 text-slate-300">
                                            {item.storageId?.name || 'Unassigned'}
                                        </td>
                                        <td className="p-4 text-right">
                                            <span className={`font-semibold ${item.isLowStock ? 'text-red-400' : 'text-white'}`}>
                                                {item.quantity?.toLocaleString()}
                                            </span>
                                            <span className="text-slate-400 ml-1">{item.unit}</span>
                                        </td>
                                        <td className="p-4 text-right text-white">
                                            ₹{item.pricePerUnit?.toFixed(2)}
                                        </td>
                                        <td className="p-4 text-center">
                                            {item.isLowStock ? (
                                                <span className="badge badge-danger">Low Stock</span>
                                            ) : (
                                                <span className="badge badge-success">In Stock</span>
                                            )}
                                        </td>
                                        <td className="p-4">
                                            <div className="flex justify-center gap-2">
                                                <button
                                                    onClick={() => openStockEntry(item)}
                                                    className="p-2 rounded-lg bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-400 transition-colors"
                                                    title="Add Stock"
                                                >
                                                    <HiOutlineArrowUp className="w-4 h-4" />
                                                </button>
                                                <button
                                                    onClick={() => openStockDeduct(item)}
                                                    className="p-2 rounded-lg bg-red-500/10 hover:bg-red-500/20 text-red-400 transition-colors"
                                                    title="Deduct Stock"
                                                >
                                                    <HiOutlineArrowDown className="w-4 h-4" />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {inventory.length === 0 && !loading && (
                <div className="text-center py-12">
                    <p className="text-slate-400">No inventory items. Add your first item!</p>
                </div>
            )}

            {/* Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                    <div className="glass-card w-full max-w-md p-6">
                        <h2 className="text-xl font-semibold text-white mb-6">
                            {modalType === 'add' && 'Add Inventory Item'}
                            {modalType === 'entry' && `Add Stock - ${selectedInventory?.productType}`}
                            {modalType === 'deduct' && `Deduct Stock - ${selectedInventory?.productType}`}
                        </h2>

                        <form onSubmit={handleSubmit} className="space-y-4">
                            {modalType === 'add' && (
                                <>
                                    <div>
                                        <label className="block text-sm font-medium text-slate-300 mb-2">Storage Room *</label>
                                        <select
                                            value={formData.storageId}
                                            onChange={(e) => setFormData({ ...formData, storageId: e.target.value })}
                                            className="input-field"
                                            required
                                        >
                                            <option value="">Select storage</option>
                                            {storages.map(s => (
                                                <option key={s._id} value={s._id}>{s.name}</option>
                                            ))}
                                        </select>
                                    </div>

                                    <div>
                                        <label className="block text-sm font-medium text-slate-300 mb-2">Product Type</label>
                                        <input
                                            type="text"
                                            value={formData.productType}
                                            onChange={(e) => setFormData({ ...formData, productType: e.target.value })}
                                            className="input-field"
                                        />
                                    </div>

                                    <div className="grid grid-cols-2 gap-4">
                                        <div>
                                            <label className="block text-sm font-medium text-slate-300 mb-2">Initial Quantity</label>
                                            <input
                                                type="number"
                                                value={formData.quantity}
                                                onChange={(e) => setFormData({ ...formData, quantity: parseFloat(e.target.value) || 0 })}
                                                className="input-field"
                                            />
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium text-slate-300 mb-2">Price/Unit (₹)</label>
                                            <input
                                                type="number"
                                                step="0.01"
                                                value={formData.pricePerUnit}
                                                onChange={(e) => setFormData({ ...formData, pricePerUnit: parseFloat(e.target.value) || 0 })}
                                                className="input-field"
                                                required
                                            />
                                        </div>
                                    </div>
                                </>
                            )}

                            {(modalType === 'entry' || modalType === 'deduct') && (
                                <>
                                    <div>
                                        <label className="block text-sm font-medium text-slate-300 mb-2">
                                            Quantity ({selectedInventory?.unit}) *
                                        </label>
                                        <input
                                            type="number"
                                            value={formData.quantity}
                                            onChange={(e) => setFormData({ ...formData, quantity: parseFloat(e.target.value) || 0 })}
                                            className="input-field"
                                            required
                                            min="1"
                                        />
                                        {modalType === 'deduct' && (
                                            <p className="text-sm text-slate-400 mt-1">
                                                Available: {selectedInventory?.quantity} {selectedInventory?.unit}
                                            </p>
                                        )}
                                    </div>

                                    {modalType === 'deduct' && (
                                        <div>
                                            <label className="block text-sm font-medium text-slate-300 mb-2">Reason</label>
                                            <select
                                                value={formData.deductType}
                                                onChange={(e) => setFormData({ ...formData, deductType: e.target.value })}
                                                className="input-field"
                                            >
                                                <option value="waste">Waste/Damage</option>
                                                <option value="transfer">Transfer</option>
                                                <option value="adjustment">Adjustment</option>
                                            </select>
                                        </div>
                                    )}

                                    <div>
                                        <label className="block text-sm font-medium text-slate-300 mb-2">Notes</label>
                                        <textarea
                                            value={formData.notes}
                                            onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                                            className="input-field"
                                            rows="2"
                                        />
                                    </div>
                                </>
                            )}

                            <div className="flex justify-end gap-3 pt-4">
                                <button
                                    type="button"
                                    onClick={() => { setShowModal(false); resetForm(); }}
                                    className="btn-secondary"
                                >
                                    Cancel
                                </button>
                                <button type="submit" className="btn-primary">
                                    {modalType === 'add' && 'Add Item'}
                                    {modalType === 'entry' && 'Add Stock'}
                                    {modalType === 'deduct' && 'Deduct Stock'}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Inventory;

import { useState, useEffect } from 'react';
import {
    HiOutlinePlus,
    HiOutlineDocumentDownload,
    HiOutlineEye,
    HiOutlineCash
} from 'react-icons/hi';
import { invoiceAPI, customerAPI, inventoryAPI } from '../services/api';
import toast from 'react-hot-toast';

const Invoices = () => {
    const [invoices, setInvoices] = useState([]);
    const [customers, setCustomers] = useState([]);
    const [inventory, setInventory] = useState([]);
    const [loading, setLoading] = useState(true);
    const [showModal, setShowModal] = useState(false);
    const [showPaymentModal, setShowPaymentModal] = useState(false);
    const [selectedInvoice, setSelectedInvoice] = useState(null);
    const [filter, setFilter] = useState('');

    const [formData, setFormData] = useState({
        customer: '',
        items: [{ productType: 'Ice Block', quantity: 1, pricePerUnit: 0, inventoryId: '' }],
        discount: 0,
        paymentMethod: 'cash',
        notes: ''
    });

    const [paymentData, setPaymentData] = useState({
        paidAmount: 0,
        paymentMethod: 'cash'
    });

    useEffect(() => {
        fetchData();
    }, [filter]);

    const fetchData = async () => {
        try {
            const [invRes, custRes, inventoryRes] = await Promise.all([
                invoiceAPI.getAll({ status: filter }),
                customerAPI.getAll({ limit: 100 }),
                inventoryAPI.getAll()
            ]);
            setInvoices(invRes.data.data);
            setCustomers(custRes.data.data);
            setInventory(inventoryRes.data.data);
        } catch (error) {
            toast.error('Failed to fetch data');
        } finally {
            setLoading(false);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            await invoiceAPI.create(formData);
            toast.success('Invoice created successfully');
            setShowModal(false);
            resetForm();
            fetchData();
        } catch (error) {
            toast.error(error.response?.data?.message || 'Failed to create invoice');
        }
    };

    const handlePayment = async (e) => {
        e.preventDefault();
        try {
            await invoiceAPI.updatePayment(selectedInvoice._id, paymentData);
            toast.success('Payment recorded');
            setShowPaymentModal(false);
            setSelectedInvoice(null);
            fetchData();
        } catch (error) {
            toast.error('Failed to record payment');
        }
    };

    const downloadPDF = async (id) => {
        try {
            const response = await invoiceAPI.downloadPDF(id);
            const url = window.URL.createObjectURL(new Blob([response.data]));
            const link = document.createElement('a');
            link.href = url;
            link.setAttribute('download', `invoice-${id}.pdf`);
            document.body.appendChild(link);
            link.click();
            link.remove();
        } catch (error) {
            toast.error('Failed to download PDF');
        }
    };

    const addItem = () => {
        setFormData({
            ...formData,
            items: [...formData.items, { productType: 'Ice Block', quantity: 1, pricePerUnit: 0, inventoryId: '' }]
        });
    };

    const removeItem = (index) => {
        if (formData.items.length > 1) {
            const newItems = formData.items.filter((_, i) => i !== index);
            setFormData({ ...formData, items: newItems });
        }
    };

    const updateItem = (index, field, value) => {
        const newItems = [...formData.items];
        newItems[index][field] = value;

        if (field === 'inventoryId' && value) {
            const inv = inventory.find(i => i._id === value);
            if (inv) {
                newItems[index].pricePerUnit = inv.pricePerUnit;
                newItems[index].productType = inv.productType;
            }
        }

        setFormData({ ...formData, items: newItems });
    };

    const resetForm = () => {
        setFormData({
            customer: '',
            items: [{ productType: 'Ice Block', quantity: 1, pricePerUnit: 0, inventoryId: '' }],
            discount: 0,
            paymentMethod: 'cash',
            notes: ''
        });
    };

    const calculateSubtotal = () => {
        return formData.items.reduce((sum, item) => sum + (item.quantity * item.pricePerUnit), 0);
    };

    const calculateTotal = () => {
        const subtotal = calculateSubtotal();
        const tax = subtotal * 0.18;
        return subtotal + tax - formData.discount;
    };

    const statusColors = {
        pending: 'badge-warning',
        partial: 'badge-info',
        paid: 'badge-success',
        overdue: 'badge-danger'
    };

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div className="flex gap-2">
                    <button
                        onClick={() => setFilter('')}
                        className={`px-4 py-2 rounded-xl text-sm transition-colors ${!filter ? 'bg-cyan-500 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'}`}
                    >
                        All
                    </button>
                    <button
                        onClick={() => setFilter('pending')}
                        className={`px-4 py-2 rounded-xl text-sm transition-colors ${filter === 'pending' ? 'bg-amber-500 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'}`}
                    >
                        Pending
                    </button>
                    <button
                        onClick={() => setFilter('paid')}
                        className={`px-4 py-2 rounded-xl text-sm transition-colors ${filter === 'paid' ? 'bg-emerald-500 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'}`}
                    >
                        Paid
                    </button>
                </div>
                <button
                    onClick={() => { setShowModal(true); resetForm(); }}
                    className="btn-primary flex items-center gap-2"
                >
                    <HiOutlinePlus className="w-5 h-5" />
                    Create Invoice
                </button>
            </div>

            {/* Invoices Table */}
            {loading ? (
                <div className="flex justify-center py-12">
                    <div className="w-10 h-10 border-4 border-cyan-500/30 border-t-cyan-500 rounded-full animate-spin"></div>
                </div>
            ) : (
                <div className="glass-card overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead>
                                <tr className="border-b border-slate-700">
                                    <th className="text-left p-4 text-slate-400 font-medium">Invoice #</th>
                                    <th className="text-left p-4 text-slate-400 font-medium">Customer</th>
                                    <th className="text-left p-4 text-slate-400 font-medium">Date</th>
                                    <th className="text-right p-4 text-slate-400 font-medium">Amount</th>
                                    <th className="text-center p-4 text-slate-400 font-medium">Status</th>
                                    <th className="text-center p-4 text-slate-400 font-medium">Actions</th>
                                </tr>
                            </thead>
                            <tbody>
                                {invoices.map((invoice) => (
                                    <tr key={invoice._id} className="table-row">
                                        <td className="p-4 text-white font-medium">{invoice.invoiceNumber}</td>
                                        <td className="p-4">
                                            <p className="text-white">{invoice.customer?.name}</p>
                                            <p className="text-sm text-slate-400">{invoice.customer?.phone}</p>
                                        </td>
                                        <td className="p-4 text-slate-300">
                                            {new Date(invoice.invoiceDate).toLocaleDateString()}
                                        </td>
                                        <td className="p-4 text-right">
                                            <p className="text-white font-semibold">₹{invoice.totalAmount?.toLocaleString()}</p>
                                            {invoice.paidAmount > 0 && invoice.paidAmount < invoice.totalAmount && (
                                                <p className="text-sm text-emerald-400">Paid: ₹{invoice.paidAmount?.toLocaleString()}</p>
                                            )}
                                        </td>
                                        <td className="p-4 text-center">
                                            <span className={`badge ${statusColors[invoice.paymentStatus]}`}>
                                                {invoice.paymentStatus}
                                            </span>
                                        </td>
                                        <td className="p-4">
                                            <div className="flex justify-center gap-2">
                                                <button
                                                    onClick={() => downloadPDF(invoice._id)}
                                                    className="p-2 rounded-lg bg-blue-500/10 hover:bg-blue-500/20 text-blue-400 transition-colors"
                                                    title="Download PDF"
                                                >
                                                    <HiOutlineDocumentDownload className="w-4 h-4" />
                                                </button>
                                                {invoice.paymentStatus !== 'paid' && (
                                                    <button
                                                        onClick={() => { setSelectedInvoice(invoice); setPaymentData({ paidAmount: invoice.totalAmount - invoice.paidAmount, paymentMethod: 'cash' }); setShowPaymentModal(true); }}
                                                        className="p-2 rounded-lg bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-400 transition-colors"
                                                        title="Record Payment"
                                                    >
                                                        <HiOutlineCash className="w-4 h-4" />
                                                    </button>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {invoices.length === 0 && !loading && (
                <div className="text-center py-12">
                    <p className="text-slate-400">No invoices yet. Create your first invoice!</p>
                </div>
            )}

            {/* Create Invoice Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                    <div className="glass-card w-full max-w-2xl max-h-[90vh] overflow-y-auto p-6">
                        <h2 className="text-xl font-semibold text-white mb-6">Create Invoice</h2>

                        <form onSubmit={handleSubmit} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-slate-300 mb-2">Customer *</label>
                                <select
                                    value={formData.customer}
                                    onChange={(e) => setFormData({ ...formData, customer: e.target.value })}
                                    className="input-field"
                                    required
                                >
                                    <option value="">Select customer</option>
                                    {customers.map(c => (
                                        <option key={c._id} value={c._id}>{c.name} - {c.phone}</option>
                                    ))}
                                </select>
                            </div>

                            <div>
                                <div className="flex justify-between items-center mb-2">
                                    <label className="text-sm font-medium text-slate-300">Items</label>
                                    <button type="button" onClick={addItem} className="text-cyan-400 text-sm hover:text-cyan-300">
                                        + Add Item
                                    </button>
                                </div>

                                {formData.items.map((item, index) => (
                                    <div key={index} className="flex gap-2 mb-2">
                                        <select
                                            value={item.inventoryId}
                                            onChange={(e) => updateItem(index, 'inventoryId', e.target.value)}
                                            className="input-field flex-1"
                                        >
                                            <option value="">Select product</option>
                                            {inventory.map(inv => (
                                                <option key={inv._id} value={inv._id}>{inv.productType} (₹{inv.pricePerUnit}/{inv.unit})</option>
                                            ))}
                                        </select>
                                        <input
                                            type="number"
                                            placeholder="Qty"
                                            value={item.quantity}
                                            onChange={(e) => updateItem(index, 'quantity', parseFloat(e.target.value) || 0)}
                                            className="input-field w-24"
                                            min="1"
                                        />
                                        <input
                                            type="number"
                                            placeholder="Price"
                                            value={item.pricePerUnit}
                                            onChange={(e) => updateItem(index, 'pricePerUnit', parseFloat(e.target.value) || 0)}
                                            className="input-field w-28"
                                        />
                                        {formData.items.length > 1 && (
                                            <button type="button" onClick={() => removeItem(index)} className="text-red-400 hover:text-red-300 px-2">
                                                ×
                                            </button>
                                        )}
                                    </div>
                                ))}
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-slate-300 mb-2">Payment Method</label>
                                    <select
                                        value={formData.paymentMethod}
                                        onChange={(e) => setFormData({ ...formData, paymentMethod: e.target.value })}
                                        className="input-field"
                                    >
                                        <option value="cash">Cash</option>
                                        <option value="upi">UPI</option>
                                        <option value="bank_transfer">Bank Transfer</option>
                                        <option value="cheque">Cheque</option>
                                        <option value="credit">Credit</option>
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-slate-300 mb-2">Discount (₹)</label>
                                    <input
                                        type="number"
                                        value={formData.discount}
                                        onChange={(e) => setFormData({ ...formData, discount: parseFloat(e.target.value) || 0 })}
                                        className="input-field"
                                    />
                                </div>
                            </div>

                            {/* Totals */}
                            <div className="bg-slate-800/50 rounded-xl p-4 space-y-2">
                                <div className="flex justify-between text-slate-300">
                                    <span>Subtotal</span>
                                    <span>₹{calculateSubtotal().toLocaleString()}</span>
                                </div>
                                <div className="flex justify-between text-slate-300">
                                    <span>GST (18%)</span>
                                    <span>₹{(calculateSubtotal() * 0.18).toLocaleString()}</span>
                                </div>
                                {formData.discount > 0 && (
                                    <div className="flex justify-between text-emerald-400">
                                        <span>Discount</span>
                                        <span>-₹{formData.discount.toLocaleString()}</span>
                                    </div>
                                )}
                                <div className="flex justify-between text-white font-bold text-lg pt-2 border-t border-slate-700">
                                    <span>Total</span>
                                    <span>₹{calculateTotal().toLocaleString()}</span>
                                </div>
                            </div>

                            <div className="flex justify-end gap-3 pt-4">
                                <button type="button" onClick={() => setShowModal(false)} className="btn-secondary">
                                    Cancel
                                </button>
                                <button type="submit" className="btn-primary">
                                    Create Invoice
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* Payment Modal */}
            {showPaymentModal && selectedInvoice && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                    <div className="glass-card w-full max-w-md p-6">
                        <h2 className="text-xl font-semibold text-white mb-4">Record Payment</h2>
                        <p className="text-slate-400 mb-6">Invoice: {selectedInvoice.invoiceNumber}</p>

                        <form onSubmit={handlePayment} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-slate-300 mb-2">Amount (₹)</label>
                                <input
                                    type="number"
                                    value={paymentData.paidAmount}
                                    onChange={(e) => setPaymentData({ ...paymentData, paidAmount: parseFloat(e.target.value) || 0 })}
                                    className="input-field"
                                    max={selectedInvoice.totalAmount - selectedInvoice.paidAmount}
                                    required
                                />
                                <p className="text-sm text-slate-400 mt-1">
                                    Due: ₹{(selectedInvoice.totalAmount - selectedInvoice.paidAmount).toLocaleString()}
                                </p>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-slate-300 mb-2">Payment Method</label>
                                <select
                                    value={paymentData.paymentMethod}
                                    onChange={(e) => setPaymentData({ ...paymentData, paymentMethod: e.target.value })}
                                    className="input-field"
                                >
                                    <option value="cash">Cash</option>
                                    <option value="upi">UPI</option>
                                    <option value="bank_transfer">Bank Transfer</option>
                                    <option value="cheque">Cheque</option>
                                </select>
                            </div>

                            <div className="flex justify-end gap-3 pt-4">
                                <button type="button" onClick={() => setShowPaymentModal(false)} className="btn-secondary">
                                    Cancel
                                </button>
                                <button type="submit" className="btn-primary">
                                    Record Payment
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Invoices;

