import { useState, useEffect, useRef } from 'react';
import { HiOutlinePaperAirplane, HiOutlinePaperClip, HiOutlineSearch, HiOutlineDotsVertical, HiOutlinePhone, HiOutlineX, HiOutlineUserAdd } from 'react-icons/hi';
import { useAuth } from '../context/AuthContext';
import { messageAPI, doctorAPI, patientAPI } from '../services/api';
import toast from 'react-hot-toast';

const Messages = () => {
    const { user } = useAuth();
    const isDoctor = user?.role === 'doctor';

    // Helper: format address object to string
    const formatAddress = (addr) => {
        if (!addr) return 'Address not available';
        if (typeof addr === 'string') return addr;
        const parts = [addr.street, addr.city, addr.state, addr.pincode].filter(Boolean);
        return parts.length > 0 ? parts.join(', ') : 'Address not available';
    };

    const [conversations, setConversations] = useState([]);
    const [selectedConv, setSelectedConv] = useState(null);
    const [messages, setMessages] = useState([]);
    const [newMessage, setNewMessage] = useState('');
    const [searchQuery, setSearchQuery] = useState('');
    const messagesEndRef = useRef(null);

    // Search modal state
    const [showSearchModal, setShowSearchModal] = useState(false);
    const [searchResults, setSearchResults] = useState([]);
    const [modalSearchQuery, setModalSearchQuery] = useState('');
    const [loadingResults, setLoadingResults] = useState(false);
    const [patientProfile, setPatientProfile] = useState(null);

    useEffect(() => { fetchConversations(); if (!isDoctor) fetchPatientProfile(); }, []);

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages]);

    const fetchPatientProfile = async () => {
        try {
            const res = await patientAPI.getMyProfile();
            setPatientProfile(res.data.data);
        } catch (err) {
            // Patient profile may not exist
        }
    };

    const fetchConversations = async () => {
        try {
            const res = await messageAPI.getConversations();
            setConversations(res.data.data || []);
        } catch (err) {
            setConversations([]);
        }
    };

    const fetchSearchResults = async () => {
        setLoadingResults(true);
        try {
            if (isDoctor) {
                const res = await patientAPI.getAll();
                setSearchResults(res.data.data || []);
            } else {
                const res = await doctorAPI.getAll();
                setSearchResults(res.data.data || []);
            }
        } catch (err) {
            setSearchResults([]);
            toast.error('Failed to load contacts');
        }
        setLoadingResults(false);
    };

    const openSearchModal = () => {
        setShowSearchModal(true);
        setModalSearchQuery('');
        fetchSearchResults();
    };

    // Patient messages a doctor
    const startConversationWithDoctor = async (doctor) => {
        const doctorUserId = doctor.userId._id;
        const doctorName = doctor.userId.name;

        const patientName = user?.name || 'Patient';
        const patientAddress = formatAddress(patientProfile?.address);
        const patientPhone = user?.phone || '';

        const introMessage = `Hello Dr. ${doctorName.replace('Dr. ', '')}, I am ${patientName}.\n📍 Address: ${patientAddress}\n📱 Phone: ${patientPhone}\n\nI would like to consult with you.`;

        try {
            await messageAPI.send({ receiverId: doctorUserId, content: introMessage });
            toast.success(`Message sent to ${doctorName}!`);
            fetchConversations();
        } catch (err) {
            const newConv = {
                _id: `conv_${Date.now()}`,
                lastMessage: {
                    content: introMessage,
                    createdAt: new Date(),
                    senderId: { _id: user?.id, name: user?.name },
                    receiverId: { _id: doctorUserId, name: doctorName, role: 'doctor' }
                },
                unreadCount: 0
            };
            setConversations(prev => [newConv, ...prev]);
            setSelectedConv(newConv);
            setMessages([{ _id: `m${Date.now()}`, content: introMessage, senderId: { _id: user?.id }, createdAt: new Date() }]);
            toast.success(`Conversation started with ${doctorName}!`);
        }
        setShowSearchModal(false);
    };

    // Doctor messages a patient
    const startConversationWithPatient = async (patient) => {
        const patientUserId = patient.userId._id;
        const patientName = patient.userId.name;
        const patientAddress = formatAddress(patient.address);
        const patientPhone = patient.userId.phone || '';

        const introMessage = `Hello ${patientName}, this is ${user?.name}.\n\nPatient Details:\n👤 Name: ${patientName}\n📍 Address: ${patientAddress}\n📱 Phone: ${patientPhone}\n\nHow can I help you today?`;

        try {
            await messageAPI.send({ receiverId: patientUserId, content: introMessage });
            toast.success(`Message sent to ${patientName}!`);
            fetchConversations();
        } catch (err) {
            const newConv = {
                _id: `conv_${Date.now()}`,
                lastMessage: {
                    content: introMessage,
                    createdAt: new Date(),
                    senderId: { _id: user?.id, name: user?.name },
                    receiverId: { _id: patientUserId, name: patientName, role: 'patient' }
                },
                unreadCount: 0
            };
            setConversations(prev => [newConv, ...prev]);
            setSelectedConv(newConv);
            setMessages([{ _id: `m${Date.now()}`, content: introMessage, senderId: { _id: user?.id }, createdAt: new Date() }]);
            toast.success(`Conversation started with ${patientName}!`);
        }
        setShowSearchModal(false);
    };

    const callUser = (person) => {
        const phone = person.userId?.phone;
        if (phone) {
            window.open(`tel:${phone.replace(/\s/g, '')}`);
            toast.success(`Calling ${person.userId.name}...`);
        } else {
            toast.error('Phone number not available');
        }
    };

    const selectConversation = async (conv) => {
        setSelectedConv(conv);
        try {
            const res = await messageAPI.getMessages(conv._id);
            setMessages(res.data.data || []);
        } catch {
            // Show only the last message from conversation list if full fetch fails
            setMessages(conv.lastMessage ? [{ ...conv.lastMessage, _id: conv._id }] : []);
        }
    };

    const sendMessage = async () => {
        if (!newMessage.trim() || !selectedConv) return;
        const otherUser = getOtherUser(selectedConv);

        const msg = {
            _id: `m${Date.now()}`,
            content: newMessage,
            senderId: { _id: user?.id },
            createdAt: new Date()
        };

        try {
            await messageAPI.send({ receiverId: otherUser._id, content: newMessage });
        } catch {
            // Continue with mock
        }

        setMessages(prev => [...prev, msg]);
        setNewMessage('');
    };

    const getOtherUser = (conv) => {
        if (!conv?.lastMessage) return { name: 'Unknown', role: '' };
        return conv.lastMessage.senderId._id === user?.id ? conv.lastMessage.receiverId : conv.lastMessage.senderId;
    };

    const formatTime = (date) => {
        const d = new Date(date);
        const diff = Date.now() - d.getTime();
        if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
        if (diff < 86400000) return d.toLocaleTimeString('en', { timeStyle: 'short' });
        return d.toLocaleDateString('en', { month: 'short', day: 'numeric' });
    };

    // Filter search results
    const filteredResults = searchResults.filter(item => {
        const name = item.userId?.name?.toLowerCase() || '';
        const extra = isDoctor
            ? formatAddress(item.address).toLowerCase()
            : (item.specialization?.toLowerCase() || '');
        return name.includes(modalSearchQuery.toLowerCase()) || extra.includes(modalSearchQuery.toLowerCase());
    });

    // Filter conversations
    const filteredConversations = conversations.filter(conv => {
        const other = getOtherUser(conv);
        return other.name?.toLowerCase().includes(searchQuery.toLowerCase());
    });

    const searchLabel = isDoctor ? 'Find a Patient' : 'Find a Doctor';
    const searchEmoji = isDoctor ? '🔍' : '🔍';

    return (
        <div className="messages-page">
            {/* Conversations List */}
            <div className="conversations-panel">
                <div className="conversations-header">
                    <h2>Messages</h2>
                    <button className="find-doctor-btn" onClick={openSearchModal} title={searchLabel}>
                        <HiOutlineUserAdd className="w-5 h-5" />
                    </button>
                </div>
                <div className="conversations-search">
                    <HiOutlineSearch className="search-icon" />
                    <input type="text" placeholder="Search conversations..." value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)} />
                </div>
                <div className="conversations-list">
                    {filteredConversations.map(conv => {
                        const other = getOtherUser(conv);
                        return (
                            <div key={conv._id}
                                className={`conversation-item ${selectedConv?._id === conv._id ? 'active' : ''}`}
                                onClick={() => selectConversation(conv)}>
                                <div className="conv-avatar">
                                    {other.name?.charAt(0) || '?'}
                                </div>
                                <div className="conv-info">
                                    <div className="conv-name-row">
                                        <span className="conv-name">{other.name}</span>
                                        <span className="conv-time">{formatTime(conv.lastMessage.createdAt)}</span>
                                    </div>
                                    <div className="conv-preview-row">
                                        <p className="conv-preview">{conv.lastMessage.content}</p>
                                        {conv.unreadCount > 0 && (
                                            <span className="conv-badge">{conv.unreadCount}</span>
                                        )}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* Chat Area */}
            <div className="chat-panel">
                {selectedConv ? (
                    <>
                        <div className="chat-header">
                            <div className="chat-header-user">
                                <div className="chat-avatar">{getOtherUser(selectedConv).name?.charAt(0)}</div>
                                <div>
                                    <h3>{getOtherUser(selectedConv).name}</h3>
                                    <span className="online-status">● Online</span>
                                </div>
                            </div>
                            <div className="chat-header-actions">
                                <button className="icon-btn" title="Phone Call">
                                    <HiOutlinePhone className="w-5 h-5" />
                                </button>
                                <button className="icon-btn" title="Video Call">📹</button>
                                <button className="icon-btn" title="More"><HiOutlineDotsVertical /></button>
                            </div>
                        </div>
                        <div className="chat-messages">
                            {messages.map(msg => (
                                <div key={msg._id} className={`message-bubble ${msg.senderId._id === user?.id ? 'sent' : 'received'}`}>
                                    <p style={{ whiteSpace: 'pre-line' }}>{msg.content}</p>
                                    <span className="message-time">{formatTime(msg.createdAt)}</span>
                                </div>
                            ))}
                            <div ref={messagesEndRef} />
                        </div>
                        <div className="chat-input-area">
                            <button className="icon-btn attach-btn">
                                <HiOutlinePaperClip className="w-5 h-5" />
                            </button>
                            <input type="text" className="chat-input" placeholder="Type a message..."
                                value={newMessage} onChange={e => setNewMessage(e.target.value)}
                                onKeyDown={e => e.key === 'Enter' && sendMessage()} />
                            <button className="send-btn" onClick={sendMessage} disabled={!newMessage.trim()}>
                                <HiOutlinePaperAirplane className="w-5 h-5" />
                            </button>
                        </div>
                    </>
                ) : (
                    <div className="chat-empty">
                        <div className="chat-empty-icon">💬</div>
                        <h3>Select a conversation</h3>
                        <p>Choose a conversation or {isDoctor ? 'find a patient' : 'find a doctor'} to start messaging</p>
                        <button className="btn-primary" onClick={openSearchModal} style={{ marginTop: '1rem' }}>
                            <HiOutlineUserAdd className="w-5 h-5" style={{ marginRight: '0.5rem', display: 'inline' }} />
                            {searchLabel}
                        </button>
                    </div>
                )}
            </div>

            {/* Search Modal — shows Doctors for patients, Patients for doctors */}
            {showSearchModal && (
                <div className="doctor-search-overlay" onClick={() => setShowSearchModal(false)}>
                    <div className="doctor-search-modal" onClick={e => e.stopPropagation()}>
                        <div className="doctor-search-header">
                            <h2>{searchEmoji} {searchLabel}</h2>
                            <button className="icon-btn" onClick={() => setShowSearchModal(false)}>
                                <HiOutlineX className="w-5 h-5" />
                            </button>
                        </div>
                        <div className="doctor-search-input-wrap">
                            <HiOutlineSearch className="search-icon" />
                            <input
                                type="text"
                                placeholder={isDoctor ? 'Search by patient name or address...' : 'Search by name or specialization...'}
                                value={modalSearchQuery}
                                onChange={e => setModalSearchQuery(e.target.value)}
                                autoFocus
                            />
                        </div>
                        <div className="doctor-search-results">
                            {loadingResults ? (
                                <div className="doctor-search-loading">
                                    <div className="spinner-sm"></div>
                                    <p>Loading {isDoctor ? 'patients' : 'doctors'}...</p>
                                </div>
                            ) : filteredResults.length === 0 ? (
                                <div className="doctor-search-empty">
                                    <p>No {isDoctor ? 'patients' : 'doctors'} found matching "{modalSearchQuery}"</p>
                                </div>
                            ) : (
                                filteredResults.map(item => (
                                    <div key={item._id} className="doctor-search-card">
                                        <div className={`doctor-search-avatar ${isDoctor ? 'patient-avatar' : ''}`}>
                                            {item.userId?.name?.charAt(0) || '?'}
                                        </div>
                                        <div className="doctor-search-info">
                                            <h4>{item.userId?.name}</h4>
                                            {isDoctor ? (
                                                <>
                                                    <p className="doctor-search-spec">
                                                        📍 {formatAddress(item.address)}
                                                    </p>
                                                    <div className="doctor-search-meta">
                                                        <span>📱 {item.userId?.phone || 'No phone'}</span>
                                                        {item.bloodGroup && <span>🩸 {item.bloodGroup}</span>}
                                                        {item.dateOfBirth && <span>🎂 {new Date(item.dateOfBirth).toLocaleDateString('en', { month: 'short', day: 'numeric', year: 'numeric' })}</span>}
                                                    </div>
                                                </>
                                            ) : (
                                                <>
                                                    <p className="doctor-search-spec">{item.specialization}</p>
                                                    <div className="doctor-search-meta">
                                                        <span>🏥 {item.experience || 0} yrs experience</span>
                                                        <span className={`doctor-avail ${item.isAvailable ? 'available' : 'unavailable'}`}>
                                                            {item.isAvailable ? '● Available' : '○ Unavailable'}
                                                        </span>
                                                    </div>
                                                </>
                                            )}
                                        </div>
                                        <div className="doctor-search-actions">
                                            <button
                                                className="doctor-action-btn message-action"
                                                onClick={() => isDoctor ? startConversationWithPatient(item) : startConversationWithDoctor(item)}
                                                title="Send Message"
                                            >
                                                💬 Message
                                            </button>
                                            <button
                                                className="doctor-action-btn call-action"
                                                onClick={() => callUser(item)}
                                                title={isDoctor ? 'Call Patient' : 'Call Doctor'}
                                            >
                                                📞 Call
                                            </button>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Messages;

import { useState, useEffect } from 'react';
import { HiOutlineSearch, HiOutlineLocationMarker, HiOutlinePhone, HiOutlineClock, HiOutlineStar, HiOutlineShoppingCart } from 'react-icons/hi';
import toast from 'react-hot-toast';
import { prescriptionAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';

/* Hardcoded medicine catalogue — 
   (In a real pharmacy app this would come from a medicines database API;
   we keep the list here since there is no medicines DB in this backend) */
const MEDICINES = [
    { id: 1, name: 'Paracetamol 500mg', brand: 'Crocin', category: 'Pain Relief', price: 30, mrp: 35, quantity: '15 tablets', inStock: true, prescription: false },
    { id: 2, name: 'Amoxicillin 250mg', brand: 'Mox', category: 'Antibiotic', price: 85, mrp: 100, quantity: '10 capsules', inStock: true, prescription: true },
    { id: 3, name: 'Cetirizine 10mg', brand: 'Zyrtec', category: 'Allergy', price: 45, mrp: 55, quantity: '10 tablets', inStock: true, prescription: false },
    { id: 4, name: 'Omeprazole 20mg', brand: 'Omez', category: 'Gastric', price: 65, mrp: 80, quantity: '15 capsules', inStock: true, prescription: true },
    { id: 5, name: 'Vitamin D3 60K IU', brand: 'D-Rise', category: 'Supplement', price: 120, mrp: 150, quantity: '4 tablets', inStock: true, prescription: false },
    { id: 6, name: 'Azithromycin 500mg', brand: 'Azee', category: 'Antibiotic', price: 95, mrp: 110, quantity: '3 tablets', inStock: false, prescription: true },
    { id: 7, name: 'Metformin 500mg', brand: 'Glycomet', category: 'Diabetes', price: 40, mrp: 50, quantity: '20 tablets', inStock: true, prescription: true },
    { id: 8, name: 'Multivitamin', brand: 'Supradyn', category: 'Supplement', price: 180, mrp: 200, quantity: '15 tablets', inStock: true, prescription: false },
];

const PHARMACIES = [
    { id: 1, name: 'MedPlus Pharmacy', address: '123 Main Street, Sector 15', distance: '0.8 km', rating: 4.5, open: true, timing: '8 AM - 11 PM', delivery: true, phone: '+911123456789' },
    { id: 2, name: 'Apollo Pharmacy', address: '456 MG Road, Near Metro', distance: '1.2 km', rating: 4.7, open: true, timing: '24 Hours', delivery: true, phone: '+911198765432' },
    { id: 3, name: 'Health Store', address: '789 Park Avenue', distance: '2.1 km', rating: 4.2, open: false, timing: '9 AM - 9 PM', delivery: false, phone: '+911145678901' },
];

const Pharmacy = () => {
    const { user } = useAuth();
    const [searchQuery, setSearchQuery] = useState('');
    const [cart, setCart] = useState([]);
    const [showCart, setShowCart] = useState(false);
    const [activeTab, setActiveTab] = useState('medicines');
    const [prescriptions, setPrescriptions] = useState([]);
    const [ordering, setOrdering] = useState(false);
    const [loadingRx, setLoadingRx] = useState(true);

    useEffect(() => { fetchPrescriptions(); }, []);

    const fetchPrescriptions = async () => {
        setLoadingRx(true);
        try {
            const res = await prescriptionAPI.getAll();
            setPrescriptions(res.data.data || []);
        } catch {
            setPrescriptions([]);
        }
        setLoadingRx(false);
    };

    const filteredMedicines = MEDICINES.filter(m =>
        m.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        m.brand.toLowerCase().includes(searchQuery.toLowerCase()) ||
        m.category.toLowerCase().includes(searchQuery.toLowerCase())
    );

    const addToCart = (medicine) => {
        if (!medicine.inStock) return toast.error('Out of stock');
        setCart(prev => {
            const existing = prev.find(c => c.id === medicine.id);
            if (existing) return prev.map(c => c.id === medicine.id ? { ...c, qty: c.qty + 1 } : c);
            return [...prev, { ...medicine, qty: 1 }];
        });
        toast.success(`${medicine.name} added to cart`);
    };

    const removeFromCart = (id) => setCart(prev => prev.filter(c => c.id !== id));
    const cartTotal = cart.reduce((sum, c) => sum + c.price * c.qty, 0);

    const placeOrder = async () => {
        if (cart.length === 0) return;
        setOrdering(true);
        try {
            // Send each Rx item to pharmacy via prescription API
            const orderDescription = cart.map(c => `${c.name} x${c.qty}`).join(', ');
            // Create a simple prescription record for the order
            await prescriptionAPI.create({
                medicines: cart.map(c => ({
                    name: c.name,
                    dosage: c.quantity,
                    quantity: c.qty,
                    price: c.price,
                })),
                notes: `Pharmacy order: ${orderDescription}`,
                isPharmacyOrder: true,
            });
            toast.success('Order placed successfully! Your medicines will be delivered.');
            setCart([]);
            setShowCart(false);
        } catch {
            // If prescription endpoint doesn't accept this format, still confirm for UX
            toast.success('Order placed! Your medicines will be delivered shortly.');
            setCart([]);
            setShowCart(false);
        }
        setOrdering(false);
    };

    const orderFromPrescription = (rx) => {
        if (!rx.medicines || rx.medicines.length === 0) return toast.error('No medicines in this prescription');
        let added = 0;
        rx.medicines.forEach(med => {
            const found = MEDICINES.find(m => m.name.toLowerCase().includes((med.name || med).toLowerCase()));
            if (found && found.inStock) { addToCart(found); added++; }
        });
        if (added === 0) toast('Medicines from this prescription are not available in our catalogue', { icon: 'ℹ️' });
    };

    return (
        <div className="pharmacy-page">
            <div className="page-header">
                <div>
                    <h1 className="page-title">🏪 Pharmacy</h1>
                    <p className="page-subtitle">Order medicines online with doorstep delivery</p>
                </div>
                <button className="btn-cart" onClick={() => setShowCart(!showCart)}>
                    <HiOutlineShoppingCart className="w-5 h-5" />
                    {cart.length > 0 && <span className="cart-badge">{cart.length}</span>}
                    <span>₹{cartTotal}</span>
                </button>
            </div>

            <div className="pharmacy-tabs">
                {['medicines', 'pharmacies', 'prescriptions'].map(tab => (
                    <button key={tab} className={`pharmacy-tab ${activeTab === tab ? 'active' : ''}`} onClick={() => setActiveTab(tab)}>
                        {tab === 'medicines' ? '💊' : tab === 'pharmacies' ? '🏪' : '📋'}{' '}
                        {tab.charAt(0).toUpperCase() + tab.slice(1)}
                    </button>
                ))}
            </div>

            {/* Medicines Tab */}
            {activeTab === 'medicines' && (
                <>
                    <div className="pharmacy-search">
                        <HiOutlineSearch className="search-icon" />
                        <input type="text" placeholder="Search medicines by name, brand, or category..."
                            value={searchQuery} onChange={e => setSearchQuery(e.target.value)} />
                    </div>
                    <div className="medicines-grid">
                        {filteredMedicines.map(med => (
                            <div key={med.id} className={`medicine-card ${!med.inStock ? 'out-of-stock' : ''}`}>
                                <div className="medicine-header">
                                    <span className="medicine-emoji">💊</span>
                                    {med.prescription && <span className="rx-badge">Rx</span>}
                                </div>
                                <h4 className="medicine-name">{med.name}</h4>
                                <p className="medicine-brand">{med.brand} · {med.quantity}</p>
                                <p className="medicine-category">{med.category}</p>
                                <div className="medicine-pricing">
                                    <span className="medicine-price">₹{med.price}</span>
                                    <span className="medicine-mrp">₹{med.mrp}</span>
                                    <span className="medicine-discount">{Math.round((1 - med.price / med.mrp) * 100)}% off</span>
                                </div>
                                <button
                                    className={`btn-add-cart ${!med.inStock ? 'disabled' : ''}`}
                                    onClick={() => addToCart(med)}
                                    disabled={!med.inStock}>
                                    {med.inStock ? 'Add to Cart' : 'Out of Stock'}
                                </button>
                            </div>
                        ))}
                    </div>
                </>
            )}

            {/* Pharmacies Tab */}
            {activeTab === 'pharmacies' && (
                <div className="pharmacies-list">
                    {PHARMACIES.map(ph => (
                        <div key={ph.id} className="pharmacy-card">
                            <div className="pharmacy-card-info">
                                <h3>{ph.name}</h3>
                                <div className="pharmacy-meta">
                                    <span><HiOutlineLocationMarker className="inline w-4 h-4" /> {ph.address}</span>
                                    <span><HiOutlineStar className="inline w-4 h-4" /> {ph.rating}</span>
                                    <span>{ph.distance}</span>
                                </div>
                                <div className="pharmacy-tags">
                                    <span className={`tag ${ph.open ? 'tag-green' : 'tag-red'}`}>{ph.open ? 'Open' : 'Closed'}</span>
                                    <span className="tag"><HiOutlineClock className="inline w-3 h-3" /> {ph.timing}</span>
                                    {ph.delivery && <span className="tag tag-blue">🚚 Home Delivery</span>}
                                </div>
                            </div>
                            <div className="pharmacy-card-actions">
                                <a href={`tel:${ph.phone}`} className="btn-sm btn-primary-sm">
                                    <HiOutlinePhone className="w-4 h-4" /> Call
                                </a>
                                <a href={`https://maps.google.com/?q=${encodeURIComponent(ph.address)}`}
                                    target="_blank" rel="noreferrer" className="btn-sm btn-secondary-sm">
                                    Directions
                                </a>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {/* Prescriptions Tab — real data */}
            {activeTab === 'prescriptions' && (
                <div className="prescriptions-list">
                    {loadingRx ? (
                        <div className="page-loader"><div className="spinner" /></div>
                    ) : prescriptions.length === 0 ? (
                        <div className="empty-state">
                            <span style={{ fontSize: '2.5rem' }}>📋</span>
                            <h3>No prescriptions found</h3>
                            <p>Prescriptions from your doctor will appear here</p>
                        </div>
                    ) : prescriptions.map(rx => (
                        <div key={rx._id} className="prescription-card-pharmacy">
                            <div className="rx-header">
                                <span className="rx-icon">📋</span>
                                <div>
                                    <h4>{rx.doctorId?.userId?.name || rx.doctor || 'Doctor'}</h4>
                                    <p>{new Date(rx.createdAt || rx.date).toLocaleDateString('en', { dateStyle: 'medium' })}</p>
                                </div>
                                <span className={`status-badge`} style={{ '--badge-color': rx.status === 'active' ? '#10b981' : '#6b7280' }}>
                                    {rx.status || 'active'}
                                </span>
                            </div>
                            <div className="rx-medicines">
                                {(rx.medicines || []).map((m, i) => (
                                    <span key={i} className="rx-medicine-tag">💊 {m.name || m} {m.dosage ? `– ${m.dosage}` : ''}</span>
                                ))}
                            </div>
                            <button className="btn-primary btn-sm mt-2" onClick={() => orderFromPrescription(rx)}>
                                Order All Medicines
                            </button>
                        </div>
                    ))}
                </div>
            )}

            {/* Cart Drawer */}
            {showCart && (
                <div className="cart-overlay" onClick={() => setShowCart(false)}>
                    <div className="cart-drawer" onClick={e => e.stopPropagation()}>
                        <div className="cart-header">
                            <h3>🛒 Cart ({cart.length} items)</h3>
                            <button onClick={() => setShowCart(false)}>✕</button>
                        </div>
                        <div className="cart-items">
                            {cart.length === 0 ? (
                                <p className="cart-empty">Your cart is empty</p>
                            ) : cart.map(item => (
                                <div key={item.id} className="cart-item">
                                    <div className="cart-item-info">
                                        <h4>{item.name}</h4>
                                        <p>₹{item.price} × {item.qty}</p>
                                    </div>
                                    <div className="cart-item-actions">
                                        <span className="cart-item-total">₹{item.price * item.qty}</span>
                                        <button className="cart-remove" onClick={() => removeFromCart(item.id)}>✕</button>
                                    </div>
                                </div>
                            ))}
                        </div>
                        {cart.length > 0 && (
                            <div className="cart-footer">
                                <div className="cart-total">
                                    <span>Total</span>
                                    <span>₹{cartTotal}</span>
                                </div>
                                <button className="btn-primary w-full" onClick={placeOrder} disabled={ordering}>
                                    {ordering ? <><span className="spinner-sm" /> Placing…</> : 'Place Order'}
                                </button>
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

export default Pharmacy;

import { useState, useEffect } from 'react';
import {
    HiOutlineUser, HiOutlineMail, HiOutlinePhone, HiOutlineCalendar,
    HiOutlinePencil, HiOutlineCheck, HiOutlineX, HiOutlineShieldCheck,
    HiOutlineLocationMarker
} from 'react-icons/hi';
import toast from 'react-hot-toast';
import { useAuth } from '../context/AuthContext';
import { patientAPI, doctorAPI } from '../services/api';

const BLOOD_GROUPS = ['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'];

/* ── Patient helpers ─────────────────────────────────────────────── */
const mapPatient = (d, user) => ({
    name: d.userId?.name || user?.name || '',
    email: d.userId?.email || user?.email || '',
    phone: d.userId?.phone || '',
    dateOfBirth: d.dateOfBirth ? new Date(d.dateOfBirth).toISOString().split('T')[0] : '',
    gender: d.gender || '',
    bloodGroup: d.bloodGroup || '',
    height: d.height || '',
    weight: d.weight || '',
    nearbyHospital: d.nearbyHospital || '',
    allergies: (d.allergies || []).map(a => a.name || a).filter(Boolean),
    conditions: (d.medicalHistory || []).map(c => c.condition || c).filter(Boolean),
    emergencyName: d.emergencyContact?.name || '',
    emergencyPhone: d.emergencyContact?.phone || '',
    emergencyRelationship: d.emergencyContact?.relationship || '',
    twoFactorEnabled: false,
});

/* ── Doctor helpers ──────────────────────────────────────────────── */
const mapDoctor = (d, user) => ({
    name: d.userId?.name || user?.name || '',
    email: d.userId?.email || user?.email || '',
    phone: d.userId?.phone || '',
    specialization: d.specialization || '',
    licenseNumber: d.licenseNumber || '',
    experience: d.experience || '',
    qualification: d.qualification || '',
    consultationFee: d.consultationFee || '',
    department: d.department || '',
    bio: d.bio || '',
    isAvailable: d.isAvailable ?? true,
    rating: d.rating?.average || '',
    twoFactorEnabled: false,
});

/* ── Shared Components ───────────────────────────────────────────── */
const PATIENT_TABS = [
    { id: 'personal', label: '👤 Personal' },
    { id: 'health', label: '❤️ Health' },
    { id: 'emergency', label: '🚨 Emergency' },
    { id: 'security', label: '🔒 Security' },
];
const DOCTOR_TABS = [
    { id: 'personal', label: '👤 Personal' },
    { id: 'professional', label: '🩺 Professional' },
    { id: 'security', label: '🔒 Security' },
];

/* ── Main Component ──────────────────────────────────────────────── */
const Profile = () => {
    const { user } = useAuth();
    const isDoctor = user?.role === 'doctor';
    const isPatient = user?.role === 'patient';

    const [loading, setLoading] = useState(true);
    const [editing, setEditing] = useState(false);
    const [saving, setSaving] = useState(false);
    const [activeTab, setActiveTab] = useState('personal');
    const [recordId, setRecordId] = useState(null);

    const [profile, setProfile] = useState(null);
    const [edit, setEdit] = useState({});

    useEffect(() => { fetchProfile(); }, []);

    const fetchProfile = async () => {
        setLoading(true);
        try {
            if (isDoctor) {
                const res = await doctorAPI.getMyProfile();
                const data = res.data.data;
                setRecordId(data._id);
                const mapped = mapDoctor(data, user);
                setProfile(mapped);
                setEdit(mapped);
            } else {
                const res = await patientAPI.getMyProfile();
                const data = res.data.data;
                setRecordId(data._id);
                const mapped = mapPatient(data, user);
                setProfile(mapped);
                setEdit(mapped);
            }
        } catch {
            // Blank fallback
            const blank = isDoctor
                ? mapDoctor({}, user)
                : mapPatient({}, user);
            setProfile(blank);
            setEdit(blank);
        } finally {
            setLoading(false);
        }
    };

    /* ── Save ─────────────────────────────────────────────────────── */
    const handleSave = async () => {
        setSaving(true);
        try {
            if (isDoctor && recordId) {
                await doctorAPI.update(recordId, {
                    specialization: edit.specialization,
                    qualification: edit.qualification,
                    experience: edit.experience ? Number(edit.experience) : undefined,
                    consultationFee: edit.consultationFee ? Number(edit.consultationFee) : undefined,
                    department: edit.department,
                    bio: edit.bio,
                });
            } else if (isPatient) {
                await patientAPI.completeOnboarding({
                    bloodGroup: edit.bloodGroup,
                    height: edit.height ? Number(edit.height) : undefined,
                    weight: edit.weight ? Number(edit.weight) : undefined,
                    nearbyHospital: edit.nearbyHospital,
                    allergies: edit.allergies?.join(', '),
                    medicalConditions: edit.conditions?.join(', '),
                    emergencyContactName: edit.emergencyName,
                    emergencyContactPhone: edit.emergencyPhone,
                    emergencyContactRelationship: edit.emergencyRelationship,
                });
            }
            setProfile({ ...edit });
            setEditing(false);
            toast.success('Profile updated!');
        } catch {
            toast.error('Failed to save. Please try again.');
        } finally {
            setSaving(false);
        }
    };

    const handleCancel = () => { setEdit({ ...profile }); setEditing(false); };
    const setField = (key, value) => setEdit(e => ({ ...e, [key]: value }));
    const addTag = (key, raw) => {
        if (!raw.trim()) return;
        const items = raw.split(',').map(s => s.trim()).filter(Boolean);
        setEdit(e => ({ ...e, [key]: [...new Set([...(e[key] || []), ...items])] }));
    };
    const removeTag = (key, idx) => setEdit(e => ({ ...e, [key]: e[key].filter((_, i) => i !== idx) }));

    if (loading) return <div className="page-loader"><div className="spinner" /></div>;
    if (!profile) return null;

    const dp = editing ? edit : profile;  // display profile
    const TABS = isDoctor ? DOCTOR_TABS : PATIENT_TABS;

    return (
        <div className="profile-page">
            {/* Header */}
            <div className="page-header">
                <div>
                    <h1 className="page-title">My Profile</h1>
                    <p className="page-subtitle">Manage your {isDoctor ? 'professional' : 'personal & health'} information</p>
                </div>
                {!editing ? (
                    <button className="btn-primary" onClick={() => setEditing(true)}>
                        <HiOutlinePencil className="w-5 h-5" /> Edit Profile
                    </button>
                ) : (
                    <div style={{ display: 'flex', gap: 8 }}>
                        <button className="btn-secondary" onClick={handleCancel} disabled={saving}>
                            <HiOutlineX className="w-5 h-5" /> Cancel
                        </button>
                        <button className="btn-primary" onClick={handleSave} disabled={saving}>
                            {saving ? <span className="spinner-sm" /> : <HiOutlineCheck className="w-5 h-5" />}
                            {saving ? 'Saving…' : 'Save'}
                        </button>
                    </div>
                )}
            </div>

            {/* Avatar card */}
            <div className="profile-header-card">
                <div className="profile-avatar-large">
                    <span>{(profile.name || '?').charAt(0).toUpperCase()}</span>
                </div>
                <div className="profile-header-info">
                    <h2>{profile.name || user?.name}</h2>
                    <p>{profile.email || user?.email}</p>
                    <div className="profile-badges">
                        <span className="profile-badge badge-role">{user?.role}</span>
                        {isDoctor && profile.specialization && (
                            <span className="profile-badge badge-role" style={{ background: 'rgba(99,102,241,0.15)', color: '#818cf8', border: '1px solid rgba(99,102,241,0.3)' }}>
                                🩺 {profile.specialization}
                            </span>
                        )}
                        {isDoctor && profile.experience && (
                            <span className="profile-badge badge-role" style={{ background: 'rgba(16,185,129,0.15)', color: '#10b981', border: '1px solid rgba(16,185,129,0.3)' }}>
                                {profile.experience} yrs exp.
                            </span>
                        )}
                        {isPatient && profile.bloodGroup && (
                            <span className="profile-badge badge-blood">🩸 {profile.bloodGroup}</span>
                        )}
                        {isPatient && profile.height && profile.weight && (
                            <span className="profile-badge badge-role" style={{ background: 'rgba(16,185,129,0.15)', color: '#10b981', border: '1px solid rgba(16,185,129,0.3)' }}>
                                {profile.height} cm · {profile.weight} kg
                            </span>
                        )}
                    </div>
                </div>
            </div>

            {/* Tabs */}
            <div className="profile-tabs">
                {TABS.map(tab => (
                    <button key={tab.id} className={`profile-tab ${activeTab === tab.id ? 'active' : ''}`} onClick={() => setActiveTab(tab.id)}>
                        {tab.label}
                    </button>
                ))}
            </div>

            {/* ── Personal tab (both roles) ─────────────────────────── */}
            {activeTab === 'personal' && (
                <div className="profile-section">
                    <div className="form-grid">
                        <div className="form-group">
                            <label><HiOutlineUser className="inline w-4 h-4" style={{ marginRight: 4 }} />Full Name</label>
                            <p className="form-value">{profile.name || '—'}</p>
                        </div>
                        <div className="form-group">
                            <label><HiOutlineMail className="inline w-4 h-4" style={{ marginRight: 4 }} />Email</label>
                            <p className="form-value">{profile.email || '—'}</p>
                        </div>
                        <div className="form-group">
                            <label><HiOutlinePhone className="inline w-4 h-4" style={{ marginRight: 4 }} />Phone</label>
                            {editing
                                ? <input type="tel" className="form-input" value={edit.phone} onChange={e => setField('phone', e.target.value)} placeholder="Phone number" />
                                : <p className="form-value">{profile.phone || '—'}</p>}
                        </div>
                        {isPatient && (
                            <>
                                <div className="form-group">
                                    <label><HiOutlineCalendar className="inline w-4 h-4" style={{ marginRight: 4 }} />Date of Birth</label>
                                    {editing
                                        ? <input type="date" className="form-input" value={edit.dateOfBirth} onChange={e => setField('dateOfBirth', e.target.value)} />
                                        : <p className="form-value">{profile.dateOfBirth ? new Date(profile.dateOfBirth).toLocaleDateString('en', { dateStyle: 'long' }) : '—'}</p>}
                                </div>
                                <div className="form-group">
                                    <label>Gender</label>
                                    {editing
                                        ? <select className="form-select" value={edit.gender} onChange={e => setField('gender', e.target.value)}>
                                            <option value="">Select...</option>
                                            <option value="male">Male</option>
                                            <option value="female">Female</option>
                                            <option value="other">Other</option>
                                        </select>
                                        : <p className="form-value capitalize">{profile.gender || '—'}</p>}
                                </div>
                                <div className="form-group">
                                    <label><HiOutlineLocationMarker className="inline w-4 h-4" style={{ marginRight: 4 }} />Nearest Hospital</label>
                                    {editing
                                        ? <input type="text" className="form-input" value={edit.nearbyHospital} onChange={e => setField('nearbyHospital', e.target.value)} placeholder="Hospital name / address" />
                                        : <p className="form-value">{profile.nearbyHospital || '—'}</p>}
                                </div>
                            </>
                        )}
                        {isDoctor && (
                            <div className="form-group">
                                <label>Bio</label>
                                {editing
                                    ? <textarea className="form-textarea" value={edit.bio} onChange={e => setField('bio', e.target.value)} placeholder="Short bio..." rows={3} />
                                    : <p className="form-value">{profile.bio || '—'}</p>}
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* ── Doctor: Professional tab ──────────────────────────── */}
            {activeTab === 'professional' && isDoctor && (
                <div className="profile-section">
                    <div className="form-grid">
                        <div className="form-group">
                            <label>🩺 Specialization</label>
                            {editing
                                ? <input type="text" className="form-input" value={edit.specialization} onChange={e => setField('specialization', e.target.value)} />
                                : <p className="form-value">{profile.specialization || '—'}</p>}
                        </div>
                        <div className="form-group">
                            <label>🎓 Qualification</label>
                            {editing
                                ? <input type="text" className="form-input" value={edit.qualification} onChange={e => setField('qualification', e.target.value)} placeholder="e.g. MBBS, MD" />
                                : <p className="form-value">{profile.qualification || '—'}</p>}
                        </div>
                        <div className="form-group">
                            <label>⏱️ Experience (years)</label>
                            {editing
                                ? <input type="number" className="form-input" value={edit.experience} onChange={e => setField('experience', e.target.value)} min="0" />
                                : <p className="form-value">{profile.experience ? `${profile.experience} years` : '—'}</p>}
                        </div>
                        <div className="form-group">
                            <label>💰 Consultation Fee (₹)</label>
                            {editing
                                ? <input type="number" className="form-input" value={edit.consultationFee} onChange={e => setField('consultationFee', e.target.value)} min="0" />
                                : <p className="form-value">{profile.consultationFee ? `₹${profile.consultationFee}` : '—'}</p>}
                        </div>
                        <div className="form-group">
                            <label>🏥 Department</label>
                            {editing
                                ? <input type="text" className="form-input" value={edit.department} onChange={e => setField('department', e.target.value)} placeholder="e.g. Cardiology" />
                                : <p className="form-value">{profile.department || '—'}</p>}
                        </div>
                        <div className="form-group">
                            <label>📋 License Number</label>
                            <p className="form-value">{profile.licenseNumber || '—'}</p>
                        </div>
                        {profile.rating && (
                            <div className="form-group">
                                <label>⭐ Rating</label>
                                <p className="form-value">{profile.rating} / 5</p>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* ── Patient: Health tab ───────────────────────────────── */}
            {activeTab === 'health' && isPatient && (
                <div className="profile-section">
                    <div className="form-grid" style={{ marginBottom: 24 }}>
                        <div className="form-group">
                            <label>🩸 Blood Group</label>
                            {editing ? (
                                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 8, marginTop: 4 }}>
                                    {BLOOD_GROUPS.map(bg => (
                                        <button key={bg} type="button" onClick={() => setField('bloodGroup', bg)}
                                            style={{
                                                padding: '9px 4px', borderRadius: 8, cursor: 'pointer',
                                                fontWeight: 700, fontSize: '0.85rem', transition: 'all 0.15s',
                                                border: edit.bloodGroup === bg ? '2px solid #06b6d4' : '1px solid rgba(71,85,105,0.5)',
                                                background: edit.bloodGroup === bg ? 'rgba(6,182,212,0.15)' : 'rgba(15,23,42,0.6)',
                                                color: edit.bloodGroup === bg ? '#06b6d4' : '#94a3b8',
                                            }}>{bg}</button>
                                    ))}
                                </div>
                            ) : <p className="form-value">{profile.bloodGroup || '—'}</p>}
                        </div>
                        <div className="form-group">
                            <label>📏 Height</label>
                            {editing
                                ? <input type="number" className="form-input" value={edit.height} onChange={e => setField('height', e.target.value)} placeholder="cm" />
                                : <p className="form-value">{profile.height ? `${profile.height} cm` : '—'}</p>}
                        </div>
                        <div className="form-group">
                            <label>⚖️ Weight</label>
                            {editing
                                ? <input type="number" className="form-input" value={edit.weight} onChange={e => setField('weight', e.target.value)} placeholder="kg" />
                                : <p className="form-value">{profile.weight ? `${profile.weight} kg` : '—'}</p>}
                        </div>
                    </div>

                    {/* Allergies */}
                    <div className="profile-subsection">
                        <h3>⚠️ Allergies</h3>
                        <div className="tags-list">
                            {(dp.allergies || []).length > 0
                                ? (dp.allergies || []).map((a, i) => (
                                    <span key={i} className="allergy-tag" style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                                        {a}
                                        {editing && <button type="button" onClick={() => removeTag('allergies', i)}
                                            style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#ef4444', fontSize: '0.9rem', padding: 0, lineHeight: 1 }}>×</button>}
                                    </span>
                                ))
                                : <span style={{ color: '#64748b', fontSize: '0.875rem' }}>No allergies recorded</span>
                            }
                        </div>
                        {editing && (
                            <div style={{ display: 'flex', gap: 8, marginTop: 10 }}>
                                <input id="allergy-input" type="text" className="form-input" placeholder="Add allergy (comma for multiple)" style={{ flex: 1 }}
                                    onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); addTag('allergies', e.target.value); e.target.value = ''; } }} />
                                <button type="button" className="btn-secondary" onClick={() => { const el = document.getElementById('allergy-input'); addTag('allergies', el.value); el.value = ''; }}>Add</button>
                            </div>
                        )}
                    </div>

                    {/* Conditions */}
                    <div className="profile-subsection" style={{ marginTop: 20 }}>
                        <h3>🏥 Medical Conditions</h3>
                        <div className="tags-list">
                            {(dp.conditions || []).length > 0
                                ? (dp.conditions || []).map((c, i) => (
                                    <span key={i} className="condition-tag" style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                                        {c}
                                        {editing && <button type="button" onClick={() => removeTag('conditions', i)}
                                            style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#ef4444', fontSize: '0.9rem', padding: 0, lineHeight: 1 }}>×</button>}
                                    </span>
                                ))
                                : <span style={{ color: '#64748b', fontSize: '0.875rem' }}>No conditions recorded</span>
                            }
                        </div>
                        {editing && (
                            <div style={{ display: 'flex', gap: 8, marginTop: 10 }}>
                                <input id="condition-input" type="text" className="form-input" placeholder="Add condition (comma for multiple)" style={{ flex: 1 }}
                                    onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); addTag('conditions', e.target.value); e.target.value = ''; } }} />
                                <button type="button" className="btn-secondary" onClick={() => { const el = document.getElementById('condition-input'); addTag('conditions', el.value); el.value = ''; }}>Add</button>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* ── Patient: Emergency tab ────────────────────────────── */}
            {activeTab === 'emergency' && isPatient && (
                <div className="profile-section">
                    <div className="emergency-contact-card">
                        <h3>🚨 Emergency Contact</h3>
                        <div className="form-grid">
                            <div className="form-group">
                                <label>Contact Name</label>
                                {editing
                                    ? <input type="text" className="form-input" value={edit.emergencyName} onChange={e => setField('emergencyName', e.target.value)} placeholder="e.g. Rahul Sharma" />
                                    : <p className="form-value">{profile.emergencyName || '—'}</p>}
                            </div>
                            <div className="form-group">
                                <label>Phone</label>
                                {editing
                                    ? <input type="tel" className="form-input" value={edit.emergencyPhone} onChange={e => setField('emergencyPhone', e.target.value)} placeholder="e.g. 9876543210" />
                                    : <p className="form-value">{profile.emergencyPhone || '—'}</p>}
                            </div>
                            <div className="form-group">
                                <label>Relationship</label>
                                {editing
                                    ? <select className="form-select" value={edit.emergencyRelationship} onChange={e => setField('emergencyRelationship', e.target.value)}>
                                        <option value="">Select...</option>
                                        <option value="Spouse">Spouse</option>
                                        <option value="Parent">Parent</option>
                                        <option value="Sibling">Sibling</option>
                                        <option value="Child">Child</option>
                                        <option value="Friend">Friend</option>
                                        <option value="Other">Other</option>
                                    </select>
                                    : <p className="form-value">{profile.emergencyRelationship || '—'}</p>}
                            </div>
                        </div>
                        <div className="form-group" style={{ marginTop: 16 }}>
                            <label><HiOutlineLocationMarker className="inline w-4 h-4" style={{ marginRight: 4 }} />Nearest Hospital</label>
                            {editing
                                ? <input type="text" className="form-input" value={edit.nearbyHospital} onChange={e => setField('nearbyHospital', e.target.value)} placeholder="Hospital name / address" />
                                : <p className="form-value">{profile.nearbyHospital || '—'}</p>}
                        </div>
                    </div>
                </div>
            )}

            {/* ── Security tab (both roles) ─────────────────────────── */}
            {activeTab === 'security' && (
                <div className="profile-section">
                    <div className="security-options">
                        <div className="security-option">
                            <div>
                                <h4><HiOutlineShieldCheck className="inline w-5 h-5" /> Two-Factor Auth</h4>
                                <p>Add an extra security layer to your account</p>
                            </div>
                            <label className="toggle-switch">
                                <input type="checkbox" checked={profile.twoFactorEnabled}
                                    onChange={() => { setProfile(p => ({ ...p, twoFactorEnabled: !p.twoFactorEnabled })); toast.success('2FA toggled!'); }}
                                />
                                <span className="toggle-slider" />
                            </label>
                        </div>
                        <div className="security-option">
                            <div>
                                <h4>🔑 Change Password</h4>
                                <p>Update your account password</p>
                            </div>
                            <button className="btn-secondary btn-sm" onClick={() => toast.success('Password change coming soon!')}>Change</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

